INSERT INTO `wp_cfs_forms` (`id`, `label`, `active`, `original_id`, `unique_id`, `params`, `html`, `css`, `img_preview`, `views`, `unique_views`, `actions`, `sort_order`, `is_pro`, `ab_id`, `date_created`) VALUES
(1, 'Base Contact', 1, 0, 'wefj2', '', '[form_start][fields][form_end]', '#[SHELL_ID] {\\r\\n	[if bg_type_0 == \'color\']\\r\\n  	background-color: [bg_color_0];\\r\\n  	[elseif bg_type_0 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_0]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] label {\\r\\n	width: 100%;\\r\\n}\\r\\n/*Fields shell basic*/\\r\\n#[SHELL_ID] .cfsFieldShell input:not([type=\\\"checkbox\\\"]):not([type=\\\"radio\\\"]),\\r\\n#[SHELL_ID] .cfsFieldShell textarea,\\r\\n#[SHELL_ID] .cfsFieldShell .cfsListSelect, \\r\\n#[SHELL_ID] .cfsFieldShell .cfsCheck,\\r\\n#[SHELL_ID] .cfsFieldShell button{\\r\\n    padding: 10px;\\r\\n    width: 100%;\\r\\n    font-size: 18px;\\r\\n    line-height: normal;\\r\\n  	[if bg_type_1 == \'color\']\\r\\n  	border: 1px solid {{adjust_opacity(\\\"[bg_color_1]\\\", 0.1)}};\\r\\n    color: {{adjust_opacity(\\\"[bg_color_1]\\\", 0.7)}};\\r\\n  	background-color: {{adjust_brightness(\\\"[bg_color_1]\\\", 196)}};\\r\\n  	[elseif bg_type_1 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_1]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n    hyphens: none;\\r\\n    border-radius: 0;\\r\\n    margin: 0;\\r\\n    max-width: 100%;\\r\\n    vertical-align: baseline;\\r\\n  	display: block;\\r\\n  	height: auto;\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"button\\\"],\\r\\n#[SHELL_ID] .cfsFieldShell button {\\r\\n	cursor: pointer;\\r\\n  	font-weight: 700;\\r\\n    border: 0 none;\\r\\n    color: #fff;\\r\\n    text-transform: uppercase;\\r\\n  	-webkit-appearance: none;\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"button\\\"],\\r\\n#[SHELL_ID] .cfsFieldShell button {\\r\\n	[if bg_type_2 == \'color\']\\r\\n  	background-color: [bg_color_2];\\r\\n  	background-image: none;\\r\\n  	[elseif bg_type_2 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_2]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"]:hover, \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"button\\\"]:hover,\\r\\n#[SHELL_ID] .cfsFieldShell button:hover {\\r\\n  	[if bg_type_2 == \'color\']\\r\\n  	background-color: {{adjust_opacity(\\\"[bg_color_2]\\\", 0.7)}};\\r\\n  	[elseif bg_type_2 == \'img\']\\r\\n  	opacity: 0.7;\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"] {\\r\\n	[if bg_type_3 == \'color\']\\r\\n  	background-color: [bg_color_3];\\r\\n  	background-image: none;\\r\\n  	[elseif bg_type_3 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_3]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"]:hover {\\r\\n	[if bg_type_3 == \'color\']\\r\\n  	background-color: {{adjust_opacity(\\\"[bg_color_3]\\\", 0.7)}};\\r\\n  	[elseif bg_type_3 == \'img\']\\r\\n  	opacity: 0.7;\\r\\n  	[endif]\\r\\n}\\r\\n/* Placeholder text color -- selectors need to be separate to work. */\\r\\n#[SHELL_ID] ::-webkit-input-placeholder {\\r\\n	color: rgba(51, 51, 51, 0.7);\\r\\n}\\r\\n#[SHELL_ID] :-moz-placeholder {\\r\\n	color: rgba(51, 51, 51, 0.7);\\r\\n}\\r\\n#[SHELL_ID] ::-moz-placeholder {\\r\\n	color: rgba(51, 51, 51, 0.7);\\r\\n	opacity: 1; /* Since FF19 lowers the opacity of the placeholder by default */\\r\\n}\\r\\n#[SHELL_ID] :-ms-input-placeholder {\\r\\n	color: rgba(51, 51, 51, 0.7);\\r\\n}', 'base-contact.jpg', 0, 0, 0, 1, 0, 0, '2016-05-03 09:31:03'),
(2, 'Neon', 1, 0, 'foe42k', '', '[form_start][fields][form_end]', '#[SHELL_ID] {\\r\\n	[if bg_type_0 == \'color\']\\r\\n  	background-color: [bg_color_0];\\r\\n  	[elseif bg_type_0 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_0]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] label {\\r\\n	width: 100%;\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldCol {\\r\\n	padding: 10px 5px\\r\\n}\\r\\n/*Glow effect*/\\r\\n#[SHELL_ID] .cfsFieldShell input:not([type=\\\"checkbox\\\"]):not([type=\\\"radio\\\"]),\\r\\n#[SHELL_ID] .cfsFieldShell .cfsListSelect, \\r\\n#[SHELL_ID] .cfsFieldShell .cfsCheck,\\r\\n#[SHELL_ID] .cfsFieldShell button {\\r\\n  	[if bg_type_1 == \'color\']\\r\\n	-webkit-box-shadow: 0px 7px 5px -3px [bg_color_1];\\r\\n 	-moz-box-shadow: 0px 7px 5px -3px [bg_color_1];\\r\\n 	box-shadow: 0 7px 5px -3px [bg_color_1];\\r\\n	[endif]\\r\\n}\\r\\n#[SHELL_ID] textarea {\\r\\n	[if bg_type_1 == \'color\']\\r\\n	-webkit-box-shadow: 0 0 5px 1px [bg_color_1];\\r\\n 	-moz-box-shadow: 0 0 5px 1px [bg_color_1];\\r\\n 	box-shadow: 0 0 5px 1px [bg_color_1];\\r\\n	[endif]\\r\\n}\\r\\n/*Fields shell basic*/\\r\\n#[SHELL_ID] input:not([type=\\\"checkbox\\\"]):not([type=\\\"radio\\\"]),\\r\\n#[SHELL_ID] textarea,\\r\\n#[SHELL_ID] .cfsListSelect, \\r\\n#[SHELL_ID] .cfsCheck {\\r\\n    padding: 0 5px 5px;\\r\\n    width: 100%;\\r\\n    font-size: 18px;\\r\\n    line-height: normal;\\r\\n  	[if bg_type_1 == \'color\']\\r\\n  	border-top: none;\\r\\n  	border-left: none;\\r\\n  	border-right: none;\\r\\n  	border-bottom: 2px solid [bg_color_1];\\r\\n  	background-color: transparent;\\r\\n  	[elseif bg_type_1 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_1]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n    hyphens: none;\\r\\n    border-radius: 0;\\r\\n    margin: 0;\\r\\n    max-width: 100%;\\r\\n    vertical-align: baseline;\\r\\n  	display: block;\\r\\n  	transition-duration: 0.4s;\\r\\n  	font-style: italic;\\r\\n  	height: auto;\\r\\n}\\r\\n#[SHELL_ID] textarea {\\r\\n  	padding: 5px;\\r\\n	[if bg_type_1 == \'color\']\\r\\n  	border: 2px solid [bg_color_1];\\r\\n  	[endif]\\r\\n}\\r\\n/*Invalid input styles*/\\r\\n#[SHELL_ID] input:not([type=\\\"checkbox\\\"]):not([type=\\\"radio\\\"]):focus:invalid,\\r\\n#[SHELL_ID] textarea:focus:invalid,\\r\\n#[SHELL_ID] .cfsListSelect:focus:invalid, \\r\\n#[SHELL_ID] .cfsCheck:focus:invalid {\\r\\n	border-color: #ff0004;\\r\\n  	box-shadow: none;\\r\\n  	[if bg_type_1 == \'color\']\\r\\n	-webkit-box-shadow: 0px 7px 5px -3px #ff0004;\\r\\n 	-moz-box-shadow: 0px 7px 5px -3px #ff0004;\\r\\n 	box-shadow: 0 7px 5px -3px #ff0004;\\r\\n	[endif]\\r\\n}\\r\\n#[SHELL_ID] textarea:focus:invalid {\\r\\n	[if bg_type_1 == \'color\']\\r\\n	-webkit-box-shadow: 0 0 5px 1px #ff0004;\\r\\n 	-moz-box-shadow: 0 0 5px 1px #ff0004;\\r\\n 	box-shadow: 0 0 5px 1px #ff0004;\\r\\n	[endif]\\r\\n}\\r\\n/*Some interactions with inputs*/\\r\\n#[SHELL_ID] input:not([type=\\\"checkbox\\\"]):not([type=\\\"radio\\\"]):focus,\\r\\n#[SHELL_ID] .cfsListSelect:focus, \\r\\n#[SHELL_ID] .cfsCheck:focus {\\r\\n	[if bg_type_1 == \'color\']\\r\\n	-webkit-box-shadow: 0px 9px 5px -3px [bg_color_1];\\r\\n 	-moz-box-shadow: 0px 9px 5px -3px [bg_color_1];\\r\\n 	box-shadow: 0 9px 5px -3px [bg_color_1];\\r\\n	[endif]\\r\\n}\\r\\n#[SHELL_ID] textarea:focus {\\r\\n	[if bg_type_1 == \'color\']\\r\\n	-webkit-box-shadow: 0 0 5px 3px [bg_color_1];\\r\\n 	-moz-box-shadow: 0 0 5px 3px [bg_color_1];\\r\\n 	box-shadow: 0 0 5px 3px [bg_color_1];\\r\\n	[endif]\\r\\n}\\r\\n/*Buttons*/\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"button\\\"],\\r\\n#[SHELL_ID] .cfsFieldShell button {\\r\\n	cursor: pointer;\\r\\n  	width: auto;\\r\\n    text-transform: uppercase;\\r\\n  	font-size: 34px;\\r\\n  	padding: 10px 20px;\\r\\n  	-webkit-appearance: none;\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"button\\\"],\\r\\n#[SHELL_ID] .cfsFieldShell button {\\r\\n	[if bg_type_2 == \'color\']\\r\\n  	border: 2px solid [bg_color_2];\\r\\n  	background-color: transparent;\\r\\n  	background-image: none;\\r\\n  	color: [bg_color_2];\\r\\n  \\r\\n  	-webkit-box-shadow: 0 0 5px 1px [bg_color_2];\\r\\n 	-moz-box-shadow: 0 0 5px 1px [bg_color_2];\\r\\n 	box-shadow: 0 0 5px 1px [bg_color_2];\\r\\n  \\r\\n  	[elseif bg_type_2 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_2]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"]:hover, \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"button\\\"]:hover,\\r\\n#[SHELL_ID] .cfsFieldShell button:hover {\\r\\n  	[if bg_type_2 == \'color\']\\r\\n  	background-color: {{adjust_opacity(\\\"[bg_color_2]\\\", 0.7)}};\\r\\n  	color: #fff;\\r\\n  	[elseif bg_type_2 == \'img\']\\r\\n  	opacity: 0.7;\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"] {\\r\\n	[if bg_type_3 == \'color\']\\r\\n  	border: 2px solid [bg_color_3];\\r\\n  	background-color: transparent;\\r\\n  	background-image: none;\\r\\n  	color: [bg_color_3];\\r\\n  \\r\\n  	-webkit-box-shadow: 0 0 5px 1px [bg_color_3];\\r\\n 	-moz-box-shadow: 0 0 5px 1px [bg_color_3];\\r\\n 	box-shadow: 0 0 5px 1px [bg_color_3];\\r\\n  \\r\\n  	[elseif bg_type_3 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_3]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"]:hover {\\r\\n	[if bg_type_3 == \'color\']\\r\\n  	background-color: {{adjust_opacity(\\\"[bg_color_3]\\\", 0.7)}};\\r\\n  	color: #fff;\\r\\n  	[elseif bg_type_3 == \'img\']\\r\\n  	opacity: 0.7;\\r\\n  	[endif]\\r\\n}\\r\\n/* Placeholder text color -- selectors need to be separate to work. */\\r\\n#[SHELL_ID] ::-webkit-input-placeholder {\\r\\n	color: rgba(51, 51, 51, 0.8);\\r\\n  	font-style: italic;\\r\\n}\\r\\n#[SHELL_ID] :-moz-placeholder {\\r\\n	color: rgba(51, 51, 51, 0.8);\\r\\n  	font-style: italic;\\r\\n}\\r\\n#[SHELL_ID] ::-moz-placeholder {\\r\\n	color: rgba(51, 51, 51, 0.8);\\r\\n	opacity: 1; /* Since FF19 lowers the opacity of the placeholder by default */\\r\\n  	font-style: italic;\\r\\n}\\r\\n#[SHELL_ID] :-ms-input-placeholder {\\r\\n	color: rgba(51, 51, 51, 0.8);\\r\\n  	font-style: italic;\\r\\n}', 'neon.jpg', 0, 0, 0, 2, 0, 0, '2016-05-03 09:31:03'),
(3, 'Intransigent', 1, 0, 'uwi23o', '', '[form_start][fields][form_end]', '#[SHELL_ID] {\\r\\n	[if bg_type_0 == \'color\']\\r\\n  	background-color: [bg_color_0];\\r\\n  	[elseif bg_type_0 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_0]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] label {\\r\\n	width: 100%;\\r\\n}\\r\\n/*Form theme custom styles*/\\r\\n#[SHELL_ID] .cfsFieldShell:not([data-field-html=\\\"submit\\\"]):not([data-field-html=\\\"reset\\\"]):not([data-field-html=\\\"button\\\"]) {\\r\\n	[if bg_type_1 == \'color\']\\r\\n  	background-color: {{adjust_brightness(\\\"[bg_color_1]\\\", 11)}};\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell[data-field-html=\\\"submit\\\"] .cfsFieldInputEx input,\\r\\n#[SHELL_ID] .cfsFieldShell[data-field-html=\\\"reset\\\"] .cfsFieldInputEx input,\\r\\n#[SHELL_ID] .cfsFieldShell[data-field-html=\\\"button\\\"] .cfsFieldInputEx input {\\r\\n	float: right;\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldExLabel {\\r\\n  	font-size: 14px;\\r\\n  	padding: 10px 25px;\\r\\n	[if bg_type_1 == \'color\']\\r\\n  	color: {{adjust_brightness(\\\"[bg_color_1]\\\", 109)}};\\r\\n  	[endif]\\r\\n}\\r\\n/*Fields shell basic*/\\r\\n#[SHELL_ID] .cfsFieldShell input:not([type=\\\"checkbox\\\"]):not([type=\\\"radio\\\"]),\\r\\n#[SHELL_ID] .cfsFieldShell textarea,\\r\\n#[SHELL_ID] .cfsFieldShell .cfsListSelect, \\r\\n#[SHELL_ID] .cfsFieldShell .cfsCheck,\\r\\n#[SHELL_ID] .cfsFieldShell button  {\\r\\n    padding: 10px;\\r\\n    width: 100%;\\r\\n    font-size: 15px;\\r\\n    line-height: normal;\\r\\n  	border: none;\\r\\n  	border-radius: 0;\\r\\n  	hyphens: none;\\r\\n    margin: 0;\\r\\n    max-width: 100%;\\r\\n    vertical-align: baseline;\\r\\n  	display: block;\\r\\n  	transition-duration: 0.3s;\\r\\n  	[if bg_type_1 == \'color\']\\r\\n    color: {{adjust_brightness(\\\"[bg_color_1]\\\", 109)}};\\r\\n  	background-color: [bg_color_1];\\r\\n  	background-image: none;\\r\\n  	[elseif bg_type_1 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_1]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n  	height: auto;\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"button\\\"],\\r\\n#[SHELL_ID] .cfsFieldShell button {\\r\\n	cursor: pointer;\\r\\n  	font-weight: normal;\\r\\n    border: 0 none;\\r\\n    color: #fff;\\r\\n    text-transform: uppercase;\\r\\n  	width: auto;\\r\\n  	font-size: 20px;\\r\\n  	padding: 15px 25px;\\r\\n  	opacity: 0.7;\\r\\n  	[if bg_type_1 == \'color\']\\r\\n  	background-color: {{adjust_brightness(\\\"[bg_color_1]\\\", -20)}};\\r\\n  	background-image: none;\\r\\n  	[elseif bg_type_1 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_1]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n  	-webkit-appearance: none;\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"]:hover,\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"]:hover,\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"button\\\"]:hover,\\r\\n#[SHELL_ID] .cfsFieldShell button:hover {\\r\\n  	opacity: 1;\\r\\n}\\r\\n/* Placeholder text color -- selectors need to be separate to work. */\\r\\n#[SHELL_ID] ::-webkit-input-placeholder {\\r\\n	color: {{adjust_brightness(\\\"[bg_color_1]\\\", 51)}};\\r\\n}\\r\\n#[SHELL_ID] :-moz-placeholder {\\r\\n	color: {{adjust_brightness(\\\"[bg_color_1]\\\", 51)}};\\r\\n}\\r\\n#[SHELL_ID] ::-moz-placeholder {\\r\\n	color: {{adjust_brightness(\\\"[bg_color_1]\\\", 51)}};\\r\\n	opacity: 1; /* Since FF19 lowers the opacity of the placeholder by default */\\r\\n}\\r\\n#[SHELL_ID] :-ms-input-placeholder {\\r\\n	color: {{adjust_brightness(\\\"[bg_color_1]\\\", 51)}};\\r\\n}', 'intransigent.jpg', 0, 0, 0, 3, 0, 0, '2016-05-03 09:31:03'),
(4, 'Simple White', 1, 0, 'vbn23a', '', '[form_start][fields][form_end]', '#[SHELL_ID] {\\r\\n	[if bg_type_0 == \'color\']\\r\\n  	background-color: [bg_color_0];\\r\\n  	[elseif bg_type_0 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_0]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] label {\\r\\n	width: 100%;\\r\\n}\\r\\n/*Fields shell basic*/\\r\\n#[SHELL_ID] .cfsFieldShell input:not([type=\\\"checkbox\\\"]):not([type=\\\"radio\\\"]),\\r\\n#[SHELL_ID] .cfsFieldShell textarea,\\r\\n#[SHELL_ID] .cfsFieldShell .cfsListSelect, \\r\\n#[SHELL_ID] .cfsFieldShell .cfsCheck,\\r\\n#[SHELL_ID] .cfsFieldShell button {\\r\\n    padding: 10px;\\r\\n    width: 100%;\\r\\n    font-size: 12px;\\r\\n    line-height: normal;\\r\\n  	[if bg_type_1 == \'color\']\\r\\n  	border: 1px solid {{adjust_opacity(\\\"[bg_color_1]\\\", 1)}};\\r\\n  	background-color: {{adjust_brightness(\\\"[bg_color_1]\\\", 196)}};\\r\\n  	[elseif bg_type_1 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_1]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n    hyphens: none;\\r\\n    border-radius: 4px;\\r\\n    margin: 0;\\r\\n    max-width: 100%;\\r\\n    vertical-align: baseline;\\r\\n  	display: block;\\r\\n  	color: #333;\\r\\n  	height: auto;\\r\\n}\\r\\n#[SHELL_ID] input:not([type=\\\"checkbox\\\"]):not([type=\\\"radio\\\"]):focus,\\r\\n#[SHELL_ID] textarea:focus,\\r\\n#[SHELL_ID] .cfsListSelect:focus, \\r\\n#[SHELL_ID] .cfsChec:focus {\\r\\n	[if bg_type_2 == \'color\']\\r\\n  	border: 1px solid [bg_color_2];\\r\\n  	color: [bg_color_2];\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"button\\\"],\\r\\n#[SHELL_ID] .cfsFieldShell button {\\r\\n	cursor: pointer;\\r\\n  	font-weight: 700;\\r\\n    border: 0 none;\\r\\n    color: #fff;\\r\