(5, 'Time for tea', 1, 0, 'bso15i', '', '[form_start][fields][form_end]', '#[SHELL_ID] {\\r\\n	[if bg_type_0 == \'color\']\\r\\n  	background-color: [bg_color_0];\\r\\n  	[elseif bg_type_0 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_0]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;/**/\\r\\n	background-position: bottom right;\\r\\n  	[endif]\\r\\n	font-family: \\\"Raleway\\\", \\\"Helvetica Neue\\\", Helvetica, Arial, sans-serif;\\r\\n  	color: #FFF;\\r\\n  	font-size: 14px;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] h3 {\\r\\n  	font-weight: bold;\\r\\n  	font-size: 24px;\\r\\n  	margin-top: 30px;\\r\\n  	margin-bottom: 15px;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] label {\\r\\n  	font-weight: bold;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] form {\\r\\n  	padding: 0 25px 25px;\\r\\n	[if bg_type_1 == \'color\']\\r\\n  	background-color: {{adjust_opacity(\\\"[bg_color_1]\\\", 0.5)}};\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] label {\\r\\n  	/*padding-left: 10px;/**/\\r\\n  	color: #FFF;\\r\\n	width: 100%;\\r\\n  	font-size: 14px;\\r\\n}\\r\\n/*Fields shell basic*/\\r\\n#[SHELL_ID] .cfsFieldShell input:not([type=\\\"checkbox\\\"]):not([type=\\\"radio\\\"]),\\r\\n#[SHELL_ID] .cfsFieldShell textarea,\\r\\n#[SHELL_ID] .cfsFieldShell .cfsListSelect, \\r\\n#[SHELL_ID] .cfsFieldShell .cfsCheck,\\r\\n#[SHELL_ID] .cfsFieldShell button {\\r\\n  	border: 1px solid #FFF;\\r\\n  	color: #FFF;\\r\\n    padding: 10px;\\r\\n    width: 100%;\\r\\n    line-height: normal;\\r\\n  	background-color: inherit;\\r\\n    hyphens: none;\\r\\n    border-radius: 4px;\\r\\n    margin: 0;\\r\\n    max-width: 100%;\\r\\n    vertical-align: baseline;\\r\\n  	display: block;\\r\\n  	height: auto;\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"button\\\"],\\r\\n#[SHELL_ID] .cfsFieldShell button {\\r\\n	cursor: pointer;\\r\\n  	font-weight: 700;\\r\\n    border: 0 none;\\r\\n    color: #fff;\\r\\n    text-transform: uppercase;\\r\\n  	-webkit-appearance: none;\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"button\\\"],\\r\\n#[SHELL_ID] .cfsFieldShell button {\\r\\n	[if bg_type_2 == \'color\']\\r\\n  	background-color: [bg_color_2];\\r\\n  	background-image: none;\\r\\n  	[elseif bg_type_2 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_2]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"]:hover, \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"button\\\"]:hover,\\r\\n#[SHELL_ID] .cfsFieldShell button:hover {\\r\\n  	[if bg_type_2 == \'color\']\\r\\n  	background-color: {{adjust_opacity(\\\"[bg_color_2]\\\", 0.7)}};\\r\\n  	[elseif bg_type_2 == \'img\']\\r\\n  	opacity: 0.7;\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"] {\\r\\n	[if bg_type_3 == \'color\']\\r\\n  	background-color: [bg_color_3];\\r\\n  	background-image: none;\\r\\n  	[elseif bg_type_3 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_3]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"]:hover {\\r\\n	[if bg_type_3 == \'color\']\\r\\n  	background-color: {{adjust_opacity(\\\"[bg_color_3]\\\", 0.7)}};\\r\\n  	[elseif bg_type_3 == \'img\']\\r\\n  	opacity: 0.7;\\r\\n  	[endif]\\r\\n}\\r\\n\\r\\n#[SHELL_ID] .g-recaptcha {\\r\\n	min-height: 60px;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] [type=\\\"submit\\\"] {\\r\\n  	margin-top: 40px !important;\\r\\n	width: 150px !important;\\r\\n  	font-size: 24px;\\r\\n  	text-transform: capitalize !important;\\r\\n  	border-radius: 25px !important;\\r\\n  	float: right;\\r\\n}', 'tea-time.png', 0, 0, 0, 5, 0, 0, '2016-05-03 09:31:03'),
