(8, 'Support Service', 1, 0, 'bjl17c', '', '[form_start][fields][form_end]', '#[SHELL_ID] {\\r\\n  	[if bg_type_3 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_3]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[elseif bg_type_3 == \'color\']\\r\\n  	background-color: [bg_color_3];\\r\\n  	[else]\\r\\n  	background-color: #FFF;\\r\\n  	[endif]\\r\\n  	font-family: sans-serif;\\r\\n  	padding: 20px;\\r\\n  	width: 380px;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] .about,\\r\\n#[SHELL_ID] p {\\r\\n  	margin: 0;\\r\\n	text-align: center;\\r\\n  	color: #FFF;\\r\\n  	font-size: 14px;\\r\\n  	line-height: 1em;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] .cfsFieldShell {\\r\\n	position: relative;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] .cfsFieldShell select {\\r\\n	position: absolute;\\r\\n  	padding-left: 5px;\\r\\n  	top: 0;\\r\\n  	left: 0;\\r\\n  	width: 100%;\\r\\n  	height: 100%;\\r\\n  	box-sizing: border-box;\\r\\n  	font-family: sans-serif;\\r\\n  	font-size: 12px;\\r\\n  	color: #666059;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] p.description {\\r\\n  	line-height: 18px;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] .about div {\\r\\n	height: 100px;\\r\\n  	margin-bottom: 20px;\\r\\n  	margin-right: 40px;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] div .name {\\r\\n	font-size: 30px;\\r\\n  	line-height: 1.8em;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] div .role {\\r\\n    margin-top: -5px;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] .about > img {\\r\\n  	width: 100px;\\r\\n  	height: 100px;\\r\\n  	margin-right: 20px;\\r\\n  	margin-bottom: 20px;\\r\\n  	float: left;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] .soc_icons {\\r\\n  	margin-top: 17px;\\r\\n	margin-left: 120px;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] .soc_icons a {\\r\\n  	font-size: 0;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] .soc_icons a + a {\\r\\n  	padding-left: 3px;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] .soc_icons img {\\r\\n  	display: inline-block;\\r\\n	height: 16px;\\r\\n  	width: 16px;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] .soc_icons img:hover {\\r\\n  	opacity: 0.5;\\r\\n}\\r\\n\\r\\n\\r\\n#[SHELL_ID] label {\\r\\n	width: 100%;\\r\\n}\\r\\n/*Fields shell basic*/\\r\\n#[SHELL_ID] .cfsFieldShell input:not([type=\\\"checkbox\\\"]):not([type=\\\"radio\\\"]),\\r\\n#[SHELL_ID] .cfsFieldShell textarea,\\r\\n#[SHELL_ID] .cfsFieldShell .cfsListSelect, \\r\\n#[SHELL_ID] .cfsFieldShell .cfsCheck,\\r\\n#[SHELL_ID] .cfsFieldShell button {\\r\\n    padding: 10px;\\r\\n    width: 100%;\\r\\n    font-size: 12px;\\r\\n    line-height: normal;\\r\\n  	[if bg_type_2 == \'color\']\\r\\n	border: 1px solid {{adjust_opacity(\\\"[bg_color_2]\\\", 0.5)}};\\r\\n  	[endif]\\r\\n  	[if bg_type_0 == \'color\']\\r\\n	background-color: [bg_color_0];\\r\\n  	[endif]\\r\\n  	[if bg_type_1 == \'color\']\\r\\n	color: [bg_color_1];\\r\\n  	[endif]  \\r\\n    hyphens: none;\\r\\n    border-radius: 3px;\\r\\n    margin: 0;\\r\\n    max-width: 100%;\\r\\n    vertical-align: baseline;\\r\\n  	display: block;\\r\\n  	height: auto;\\r\\n}\\r\\n#[SHELL_ID] input:focus,\\r\\n#[SHELL_ID] textarea:focus,\\r\\n#[SHELL_ID] .cfsListSelect:focus, \\r\\n#[SHELL_ID] .cfsCheck:focus {\\r\\n    outline: none;\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"button\\\"],\\r\\n#[SHELL_ID] .cfsFieldShell button {\\r\\n	cursor: pointer;\\r\\n  	font-weight: 700;\\r\\n    border: 0 none;\\r\\n    color: #fff;\\r\\n    text-transform: uppercase;\\r\\n  	-webkit-appearance: none;\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"button\\\"],\\r\\n#[SHELL_ID] .cfsFieldShell button {\\r\\n	[if bg_type_2 == \'color\']\\r\\n  	background-color: [bg_color_2];\\r\\n  	background-image: none;\\r\\n  	[elseif bg_type_2 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_2]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n  	width: 50%;\\r\\n  	float: right;\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"]:hover, \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"button\\\"]:hover,\\r\\n#[SHELL_ID] .cfsFieldShell button:hover {\\r\\n  	[if bg_type_2 == \'color\']\\r\\n  	background-color: {{adjust_opacity(\\\"[bg_color_2]\\\", 0.7)}};\\r\\n  	[elseif bg_type_2 == \'img\']\\r\\n  	opacity: 0.7;\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"] {\\r\\n	[if bg_type_3 == \'color\']\\r\\n  	background-color: [bg_color_3];\\r\\n  	background-image: none;\\r\\n  	[elseif bg_type_3 == \'img\']\\r\\n  	background-image: url(\\\"[bg_img_3]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"]:hover {\\r\\n	[if bg_type_3 == \'color\']\\r\\n  	background-color: {{adjust_opacity(\\\"[bg_color_3]\\\", 0.7)}};\\r\\n  	[elseif bg_type_3 == \'img\']\\r\\n  	opacity: 0.7;\\r\\n  	[endif]\\r\\n}\\r\\n/* Placeholder text color -- selectors need to be separate to work. */\\r\\n#[SHELL_ID] ::-webkit-input-placeholder {\\r\\n	color: {{adjust_opacity(\\\"[bg_color_1]\\\", 0.5)}};\\r\\n}\\r\\n#[SHELL_ID] :-moz-placeholder {\\r\\n	color: {{adjust_opacity(\\\"[bg_color_1]\\\", 0.5)}};\\r\\n}\\r\\n#[SHELL_ID] ::-moz-placeholder {\\r\\n	color: {{adjust_opacity(\\\"[bg_color_1]\\\", 0.5)}};\\r\\n	opacity: 1; /* Since FF19 lowers the opacity of the placeholder by default */\\r\\n}\\r\\n#[SHELL_ID] :-ms-input-placeholder {\\r\\n	color: {{adjust_opacity(\\\"[bg_color_1]\\\", 0.5)}};\\r\\n}', 'kiwifruit.png', 0, 0, 0, 8, 0, 0, '2016-05-03 09:31:03');
