(9, 'Ho Ho Ho', 1, 0, 'ajl17d', '', '<link href=\"https://fonts.googleapis.com/css?family=Pacifico|Raleway|Raleway:800\" rel=\"stylesheet\"/>[form_start][fields][form_end]', '#[SHELL_ID] {\\r\\n	[if bg_type_0 == \\\"color\\\"]\\r\\n  	background-color: [bg_color_0];\\r\\n  	[elseif bg_type_0 == \\\"img\\\"]\\r\\n  	background-image: url(\\\"[bg_img_0]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n	\\r\\n	font-family: \\\"Raleway\\\";\\r\\n	text-align: center;\\r\\n	\\r\\n	-webkit-box-shadow: 0 0 7px rgba(0,0,0,0.5);\\r\\n	-moz-box-shadow: 0 0 7px rgba(0,0,0,0.5);\\r\\n	box-shadow: 0 0 7px rgba(0,0,0,0.5);\\r\\n}\\r\\n#[SHELL_ID] label {\\r\\n	width: 100%;\\r\\n}\\r\\n/*Fields shell basic*/\\r\\n#[SHELL_ID] .cfsFieldShell input:not([type=\\\"checkbox\\\"]):not([type=\\\"radio\\\"]),\\r\\n#[SHELL_ID] .cfsFieldShell textarea,\\r\\n#[SHELL_ID] .cfsFieldShell .cfsListSelect select, \\r\\n#[SHELL_ID] .cfsFieldShell .cfsCheck,\\r\\n#[SHELL_ID] .cfsFieldShell button {\\r\\n    padding: 10px;\\r\\n    width: 100%;\\r\\n    font-size: 14px;\\r\\n    line-height: normal;\\r\\n	margin: 0;\\r\\n  	[if bg_type_1 == \\\"color\\\"]\\r\\n  	border: 1px solid {{adjust_opacity(\\\"[bg_color_1]\\\", 0.5)}};\\r\\n    color: {{adjust_opacity(\\\"[bg_color_1]\\\", 1)}};\\r\\n  	background-color: {{adjust_brightness(\\\"[bg_color_1]\\\", 196)}};\\r\\n  	[elseif bg_type_1 == \\\"img\\\"]\\r\\n  	background-image: url(\\\"[bg_img_1]\\\");\\r\\n  	background-repeat: no-repeat;\\r\\n  	background-size: cover;\\r\\n  	[endif]\\r\\n	hyphens: none;\\r\\n    border-radius: 2px;\\r\\n    max-width: 100%;\\r\\n    vertical-align: baseline;\\r\\n  	display: block;\\r\\n  	font-family: \\\"Raleway\\\";\\r\\n  	height: auto;\\r\\n}\\r\\n#[SHELL_ID] .cfsListSelect {\\r\\n	border: 1px solid transparent;\\r\\n	padding: 0px;\\r\\n}\\r\\n\\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"submit\\\"], \\r\\n#[SHELL_ID] .cfsFieldShell input[type=\\\"reset\\\"], 