153, 153, 153, 0.5);\\r\\n  	font-family: \\\"Raleway\\\";\\r\\n}\\r\\n#[SHELL_ID] :-moz-placeholder {\\r\\n	color: rgba(153, 153, 153, 0.5);\\r\\n  	font-family: \\\"Raleway\\\";\\r\\n}\\r\\n#[SHELL_ID] ::-moz-placeholder {\\r\\n	color: rgba(153, 153, 153, 0.5);\\r\\n  	font-family: \\\"Raleway\\\";\\r\\n	opacity: 1; /* Since FF19 lowers the opacity of the placeholder by default */\\r\\n}\\r\\n#[SHELL_ID] :-ms-input-placeholder {\\r\\n	color: rgba(153, 153, 153, 0.5);\\r\\n  	font-family: \\\"Raleway\\\";\\r\\n}\\r\\n/**/\\r\\n#[SHELL_ID] .csfForm {\\r\\n	display: inline-block;\\r\\n	text-align: left;\\r\\n    padding: 0 0 20px;\\r\\n    width: 100%;\\r\\n}\\r\\n#[SHELL_ID] .csfForm  > .row {\\r\\n	width: 80%;\\r\\n	margin: 0 auto;\\r\\n}\\r\\n#[SHELL_ID] .csfForm  > .row:nth-of-type(2)  {\\r\\n	width: 100%;\\r\\n}\\r\\n#[SHELL_ID] .csfForm  > .row:first-of-type {\\r\\n    [if bg_type_4 == \\\"color\\\"]\\r\\n	background: -moz-radial-gradient(center, ellipse cover, {{ adjust_brightness(\\\"[bg_color_4]\\\", 50) }} 0%, [bg_color_4] 100%); /* ff3.6+ */\\r\\n	background: -webkit-gradient(radial, center center, 0px, center center, 100%, color-stop(0%, {{ adjust_brightness(\\\"[bg_color_4]\\\", 50) }}), color-stop(100%, [bg_color_4])); /* safari4+,chrome */\\r\\n	background:-webkit-radial-gradient(center, ellipse cover, {{ adjust_brightness(\\\"[bg_color_4]\\\", 50) }} 0%, [bg_color_4] 100%); /* safari5.1+,chrome10+ */\\r\\n	background: -o-radial-gradient(center, ellipse cover, {{ adjust_brightness(\\\"[bg_color_4]\\\", 50) }} 0%, [bg_color_4] 100%); /* opera 11.10+ */\\r\\n	background: -ms-radial-gradient(center, ellipse cover, {{ adjust_brightness(\\\"[bg_color_4]\\\", 50) }} 0%, [bg_color_4] 100%); /* ie10+ */\\r\\n	background:radial-gradient(ellipse at center, {{ adjust_brightness(\\\"[bg_color_4]\\\", 50) }} 0%, [bg_color_4] 100%); /* w3c */\\r\\n	filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\\\"{{ adjust_brightness(\\\"[bg_color_4]\\\", 50) }}\\\", endColorstr=\\\"[bg_color_4]\\\",GradientType=1 ); /* ie6-9 */\\r\\n	[elseif bg_type_4 == \\\"img\\\"]\\r\\n	background-image: url(\\\"[bg_img_4]\\\");\\r\\n	background-repeat: no-repeat;\\r\\n	background-size: cover;\\r\\n	[endif]\\r\\n	width: 100%;\\r\\n}\\r\\n#[SHELL_ID] .csfForm  > .row:first-of-type .cfsFieldCol {\\r\\n	[if bg_type_5 == \\\"color\\\"]\\r\\n	background: {{ hex_to_rgba_str(\\\"[bg_color_5]\\\", 0.9) }};\\r\\n	[elseif bg_type_5 == \\\"img\\\"]\\r\\n	background-image: url(\\\"[bg_img_5]\\\");\\r\\n	background-repeat: no-repeat;\\r\\n	background-size: cover;\\r\\n	[endif]\\r\\n	text-align: center;\\r\\n	position: relative;\\r\\n	width: 100%;\\r\\n	min-height: 329px;\\r\\n}\\r\\n/*\\r\\n#[SHELL_ID] .cfsImgWrench {\\r\\n	[if bg_type_6 == \\\"img\\\"]\\r\\n	background-image: url(\\\"[bg_img_6]\\\");\\r\\n	background-repeat: no-repeat;\\r\\n    background-size: 75% auto;\\r\\n    height: 130px;\\r\\n	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsImgSanta {\\r\\n	[if bg_type_7 == \\\"img\\\"]\\r\\n	background-image: url(\\\"[bg_img_7]\\\");\\r\\n	background-repeat: no-repeat;\\r\\n	background-size: 100% auto;\\r\\n    height: 235px;\\r\\n	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsNewYearBg > div {\\r\\n	vertical-align: middle;\\r\\n}*/\\r\\n\\r\\n#[SHELL_ID] .cfsWrapImgWrench {\\r\\n	margin-right: 130px;\\r\\n	text-align: center;\\r\\n	position: relative;\\r\\n	z-index: 100;\\r\\n	bottom: 67px;\\r\\n	width: 50%;\\r\\n}\\r\\n#[SHELL_ID] .cfsImgWrench {\\r\\n	position: absolute;\\r\\n	right: -65px;\\r\\n	\\r\\n	[if bg_type_6 == \\\"img\\\"]\\r\\n	background-image: url(\\\"[bg_img_6]\\\");\\r\\n	background-repeat: no-repeat;\\r\\n	background-size: cover;\\r\\n    height: 130px;\\r\\n    width: 130px;\\r\\n	[endif]\\r\\n}\\r\\n#[SHELL_ID] .cfsWrapImgSanta {\\r\\n	position: relative;\\r\\n	z-index: 100;\\r\\n}\\r\\n#[SHELL_ID] .cfsImgSanta {\\r\\n	position: absolute;\\r\\n	top: -130px;\\r\\n	right: 0%;\\r\\n	[if bg_type_7 == \\\"img\\\"]\\r\\n	background-image: url(\\\