(745, 327, '_elementor_data', '[{\"id\":\"56132747\",\"elType\":\"section\",\"settings\":{\"content_width\":{\"unit\":\"px\",\"size\":\"650\"},\"margin\":{\"unit\":\"px\",\"top\":\"-100\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":\"\"},\"padding_mobile\":{\"unit\":\"px\",\"top\":\"25\",\"right\":\"25\",\"bottom\":\"25\",\"left\":\"25\",\"isLinked\":\"\"},\"_title\":\"The Post\"},\"elements\":[{\"id\":\"1697ba08\",\"elType\":\"column\",\"settings\":{\"_column_size\":\"100\"},\"elements\":[{\"id\":\"255c7ad\",\"elType\":\"widget\",\"settings\":{\"image\":{\"id\":337,\"url\":\"http:\\/\\/srioms.co.in\\/wp-content\\/uploads\\/2021\\/01\\/Capture-2.png\"},\"image_size\":\"full\",\"image_border_border\":\"solid\",\"image_border_width\":{\"unit\":\"px\",\"top\":\"2\",\"right\":\"2\",\"bottom\":\"2\",\"left\":\"2\",\"isLinked\":\"1\"},\"image_border_color\":\"#ffffff\",\"image_border_radius\":{\"unit\":\"%\",\"top\":\"100\",\"right\":\"100\",\"bottom\":\"100\",\"left\":\"100\",\"isLinked\":\"1\"},\"image_box_shadow_box_shadow_type\":\"yes\",\"image_box_shadow_box_shadow\":{\"horizontal\":\"0\",\"vertical\":\"0\",\"blur\":\"38\",\"spread\":\"0\",\"inset\":\"\",\"color\":\"rgba(0,0,0,0.19)\"},\"space\":{\"unit\":\"%\",\"size\":23},\"width\":{\"unit\":\"%\",\"size\":26,\"sizes\":[]},\"height\":{\"unit\":\"px\",\"size\":130,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"image\"},{\"id\":\"2c00b844\",\"elType\":\"widget\",\"settings\":{\"title\":\"Dr. Candra Shekhar Mishra\\u00a0\",\"header_size\":\"h4\",\"align\":\"center\",\"title_color\":\"#503470\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":18},\"typography_font_weight\":\"500\",\"typography_font_family\":\"Roboto\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"293fbfc7\",\"elType\":\"widget\",\"settings\":{\"space\":{\"unit\":\"px\",\"size\":\"30\"},\"space_mobile\":{\"unit\":\"px\",\"size\":\"10\"}},\"elements\":[],\"widgetType\":\"spacer\"},{\"id\":