INSERT INTO `wp_pps_popup` (`id`, `label`, `active`, `original_id`, `params`, `html`, `css`, `img_preview`, `show_on`, `show_to`, `show_pages`, `type_id`, `views`, `unique_views`, `actions`, `date_created`, `sort_order`, `show_in_admin_area`) VALUES
(9, 'SIGN UP', 1, 0, '', '<link rel=\"stylesheet\" type=\"text/css\" href=\"//fonts.googleapis.com/css?family=Amatic+SC\" />\r\n<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<a href=\"#\" class=\"ppsPopupClose ppsPopupClose_[close_btn]\"></a>\r\n	<div class=\"ppsInnerTblContent\">\r\n		<div class=\"ppsPopupListsInner ppsPopupInner\">\r\n			[if enb_label]\r\n				<div class=\"ppsPopupLabel ppsPopupListsLabel\">[label]</div>\r\n			[endif]\r\n			<div style=\"clear: both;\"></div>\r\n			[if enb_txt_0]\r\n				<div class=\"ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0\">\r\n				[txt_0]\r\n				</div>\r\n			[endif]\r\n			[if enb_subscribe]\r\n				<div class=\"ppsSubscribeShell\">\r\n					[sub_form_start]\r\n					[sub_fields_html]\r\n					<input type=\"submit\" name=\"submit\" value=\"[sub_btn_label]\" />\r\n					[sub_form_end]\r\n					<div style=\"clear: both;\"></div>\r\n				</div>\r\n			[endif]\r\n			<div style=\"clear: both;\"></div>\r\n			<div class=\"ppsRightCol\">\r\n				[if enb_sm]\r\n					<div style=\"clear: both;\"></div>\r\n					<div class=\"ppsSm\">\r\n					[sm_html]\r\n					</div>\r\n				[endif]\r\n				[if enb_foot_note]\r\n					<div class=\"ppsFootNote\">\r\n					[foot_note]\r\n					</div>\r\n				[endif]\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	padding: 15px;\r\n  	font-family: \'arial\', arial;\r\n	font-size: 13px;\r\n	line-height: 21px;\r\n	font-weight: normal;\r\n	color: #f9e6ce;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n	display: table;\r\n  	width: 100%;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupInner {\r\n  {% if popup.params.tpl.enb_subscribe or popup.params.tpl.enb_foot_note or popup.params.tpl.enb_sm %}\r\n  	width: 100%;\r\n  	box-shadow: rgba(192,192,192,1) 0 4px 20px, 6px -6px 0px rgba(0, 0, 0, 0.1) inset;\r\n  	border-radius: 4px;\r\n	[else]\r\n  	width: 100%;\r\n  	[endif]\r\n  	display: table-cell;\r\n	[if bg_type_0 == \'color\']\r\n	background: -moz-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* ff3.6+ */\r\n	background: -webkit-gradient(radial, center center, 0px, center center, 100%, color-stop(0%, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }}), color-stop(100%, [bg_color_0])); /* safari4+,chrome */\r\n	background:-webkit-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* safari5.1+,chrome10+ */\r\n	background: -o-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* opera 11.10+ */\r\n	background: -ms-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* ie10+ */\r\n	background:radial-gradient(ellipse at center, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* w3c */\r\n	filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'{{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }}\', endColorstr=\'[bg_color_0]\',GradientType=1 ); /* ie6-9 */\r\n  	[elseif bg_type_0 == \'img\']\r\n  	background-image: url(\"[bg_img_0]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n  	\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	color: #FFF;\r\n	font-family: \'Amatic SC\', arial;\r\n	font-size: 45px;\r\n	letter-spacing: -1px;\r\n	line-height: 40px;\r\n	letter-spacing: -1px;\r\n	font-weight: bold;\r\n	margin-top: 15px;\r\n	margin-bottom: 16px;\r\n	padding-left: 20px;\r\n	-moz-text-shadow: 0px 0px 1px #000;\r\n	-webkit-text-shadow: 0px 0px 1px #000;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell form {\r\n	padding: 10% 10% 5% 5%;\r\n	text-align:right;\r\n	margin-bottom: 20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	/*width: 100%;*/\r\n  	margin-bottom: 10px;\r\n  	height: 40px;\r\n  	border: 0px solid #d1b36d;\r\n	border-radius: 4px !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=text],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	box-shadow: 2px 2px 2px #dcdcdc inset;\r\n  	padding-left: 20px;\r\n  	font-size: 17px;\r\n	width:100%;\r\n  	background-color: #fff;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect {\r\n	display: table;\r\n  	text-align: left;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelectLabel,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	display: table-cell;\r\n  	color: #000;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelectLabel {\r\n	opacity: 0.5;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	width: 100%;\r\n  	background-color: transparent;\r\n  	height: 40px;\r\n  	border: none;\r\n  	margin-left: -4px;\r\n  	font-size: 17px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	font-family: inherit;\r\n  	height: auto;\r\n    padding-top: 5px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=text],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[name=\"email\"] {\r\n	background-image: url(\"[PPS_ASSETS_URL]img/assets/email-icon.png\");\r\n  	background-repeat: no-repeat;\r\n	width:100%;\r\n	background-attachment: scroll;\r\n	background-position: 0px center;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit] {\r\n	border-color: #000;\r\n	width: 60%;\r\n  	[if bg_type_1 == \'color\']\r\n  	background: [bg_color_1] 100%;\r\n   	box-shadow: -4px -4px 0px rgba(0, 0, 0, 0.1) inset;\r\n  	background-image: none;\r\n  	[elseif bg_type_1 == \'img\']\r\n  	background-image: url(\"[bg_img_1]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n  \r\n  	color: #fff;\r\n    font-size: 20px;\r\n    text-shadow: 1px 1px 1px #000;\r\n  	cursor: pointer;\r\n  	padding: 0 6px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit]:hover {\r\n   box-shadow: 4px 4px 0px rgba(0, 0, 0, 0.1) inset;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 {\r\n	float: left;\r\n  	width: 80%;\r\n	margin-left: 10%;\r\n	text-align: justify;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n	top: 15px;\r\n  	top:15px;\r\n  	right:10px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose.ppsPopupClose_lists_black {\r\n 	top: 0 !important;\r\n  	right: 0 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote{\r\n	color: #585858;\r\n    font-family: \"Helvetica Neue\",Helvetica,Arial,sans-serif;\r\n    font-size: x-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n  	margin: 5px 30px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSm{\r\n	margin-top:20px;\r\n}\r\n#ppsPopupShell_[ID] input[name=\"name\"] {\r\n    background-image: url(\"[PPS_ASSETS_URL]img/assets/user-icon.png\");\r\n    background-repeat: no-repeat;\r\n    background-attachment: scroll;\r\n    background-position: 0px center;\r\n}', 'sing-up.jpg', 1, 1, 1, 1, 0, 0, 0, '2015-01-10 13:29:43', 3, 0),
(10, 'Informed', 1, 0, '', '<link rel=\"stylesheet\" type=\"text/css\" href=\"//fonts.googleapis.com/css?family=Amatic+SC\" />\r\n<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<a href=\"#\" class=\"ppsPopupClose ppsPopupClose_[close_btn]\"></a>\r\n	<div class=\"ppsInnerTblContent\">\r\n		<div class=\"ppsPopupListsInner ppsPopupInner\">\r\n			[if enb_label]\r\n				<div class=\"ppsPopupLabel ppsPopupListsLabel\">[label]</div>\r\n			[endif]\r\n			<div style=\"clear: both;\"></div>\r\n			[if enb_txt_0]\r\n				<div class=\"ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0\">\r\n				[txt_0]\r\n				</div>\r\n			[endif]\r\n			[if enb_subscribe]\r\n				<div class=\"ppsSubscribeShell\">\r\n					[sub_form_start]\r\n					[sub_fields_html]\r\n					<input class=\"butt\" type=\"submit\" name=\"submit\" value=\"[sub_btn_label]\" />\r\n					[sub_form_end]\r\n					<div style=\"clear: both;\"></div>\r\n				</div>\r\n			[endif]\r\n			<div style=\"clear: both;\"></div>\r\n			<div class=\"ppsRightCol\">\r\n				[if enb_sm]\r\n					<div style=\"clear: both;\"></div>\r\n					<div class=\"ppsSm\">\r\n					[sm_html]\r\n					</div>\r\n				[endif]\r\n				[if enb_foot_note]\r\n					<div class=\"ppsFootNote\">\r\n					[foot_note]\r\n					</div>\r\n				[endif]\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	padding: 15px;\r\n  	font-family: \'arial\', arial;\r\n	font-size: 13px;\r\n	line-height: 21px;\r\n	font-weight: normal;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupInner {\r\n  {% if popup.params.tpl.enb_subscribe or popup.params.tpl.enb_foot_note or popup.params.tpl.enb_sm %}\r\n  	width: 100%;\r\n  	border-radius: 4px;\r\n	[else]\r\n  	width: 100%;\r\n  	[endif]\r\n  	padding: 10px;\r\n	[if bg_type_0 == \'color\']\r\n	background: -moz-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* ff3.6+ */\r\n	background: -webkit-gradient(radial, center center, 0px, center center, 100%, color-stop(0%, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }}), color-stop(100%, [bg_color_0])); /* safari4+,chrome */\r\n	background:-webkit-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* safari5.1+,chrome10+ */\r\n	background: -o-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* opera 11.10+ */\r\n	background: -ms-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* ie10+ */\r\n	background:radial-gradient(ellipse at center, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* w3c */\r\n	filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'{{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }}\', endColorstr=\'[bg_color_0]\',GradientType=1 ); /* ie6-9 */\r\n  	[elseif bg_type_0 == \'img\']\r\n  	background-image: url(\"[bg_img_0]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n  	\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	color: #000;\r\n	text-align: center;\r\n	font-size: 45px;\r\n	letter-spacing: -1px;\r\n	line-height: 40px;\r\n	letter-spacing: -1px;\r\n	font-weight: bold;\r\n	margin-top: 15px;\r\n	margin-bottom: 16px;\r\n	padding-left: 20px;\r\n	-moz-text-shadow: 0px 0px 1px #000;\r\n	-webkit-text-shadow: 0px 0px 1px #000;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell form {\r\n	padding: 1% 1% 1% 1%;\r\n	text-align:right;\r\n	margin-bottom: 20px;\r\n  	padding-left: 20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	/*width: 100%;*/\r\n  	margin-bottom: 10px;\r\n  	height: 40px;\r\n  	border: 0px solid #d1b36d;\r\n	border-radius: 4px !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=text],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	box-shadow: 2px 2px 2px #dcdcdc inset;\r\n  	padding-left: 20px;\r\n  	font-size: 17px;\r\n	width: 100%;\r\n  	max-width: 284px;\r\n	display: block;\r\n	float: left;\r\n  	border: 1px solid #000;\r\n  	background-color: #fff;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect {\r\n	display: table;\r\n  	text-align: left;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelectLabel,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	display: table-cell;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelectLabel {\r\n	opacity: 0.5;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	width: 100%;\r\n  	background-color: transparent;\r\n  	height: 40px;\r\n  	border: none;\r\n  	font-size: 17px;\r\n	border-top-right-radius: 4px;\r\n  	border-bottom-right-radius: 4px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	font-family: inherit;\r\n  	height: auto;\r\n    padding-top: 5px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=text],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[name=\"email\"] {\r\n	width:75%;\r\n	background-attachment: scroll;\r\n	background-position: 0px center;\r\n  	border: 1px solid #000;\r\n  	display:block;\r\n  	float:left;\r\n  	padding-left:20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit] {\r\n	border-color: #000;\r\n	line-height: 1;\r\n  	display:block;\r\n  	float: left;\r\n	margin-left: 10px;\r\n  	padding: 10px;\r\n  	[if bg_type_1 == \'color\']\r\n  	background: [bg_color_1] 100%;\r\n   box-shadow: -4px -4px 0px rgba(0, 0, 0, 0.1) inset;\r\n  	background-image: none;\r\n  	[elseif bg_type_1 == \'img\']\r\n  	background-image: url(\"[bg_img_1]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n  \r\n  	color: #fff;\r\n    font-size: 20px;\r\n    text-shadow: 1px 1px 1px #000;\r\n  	cursor: pointer;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit]:hover {\r\n   box-shadow: 4px 4px 0px rgba(0, 0, 0, 0.1) inset;\r\n	\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 {\r\n	float: left;\r\n  	width: 80%;\r\n	margin-left: 10%;\r\n	text-align: center;\r\n	color: black;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n	top: 15px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose.ppsPopupClose_lists_black {\r\n 	top: 0 !important;\r\n  	right: 0 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote{\r\n	color: #585858;\r\n    font-family: \"Helvetica Neue\",Helvetica,Arial,sans-serif;\r\n    font-size: x-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n  	margin: 5px 30px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSm{\r\n	margin-top:20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubMsg{\r\n	clear: both;\r\n  	text-align: left;\r\n}\r\n\r\n\r\n\r\n', 'informed.jpg', 1, 1, 1, 1, 0, 0, 0, '2015-01-10 13:29:43', 5, 0);
INSERT INTO `wp_pps_popup` (`id`, `label`, `active`, `original_id`, `params`, `html`, `css`, `img_preview`, `show_on`, `show_to`, `show_pages`, `type_id`, `views`, `unique_views`, `actions`, `date_created`, `sort_order`, `show_in_admin_area`) VALUES
(11, 'START popup', 1, 0, '', '<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<a href=\"#\" class=\"ppsPopupClose ppsPopupClose_[close_btn]\"></a>\r\n	<div class=\"ppsInnerTblContent\">\r\n		<div class=\"ppsPopupListsInner ppsPopupInner\">\r\n			[if enb_label]\r\n				<div class=\"ppsPopupLabel ppsPopupListsLabel\">[label]</div>\r\n			[endif]\r\n			<div style=\"clear: both;\"></div>\r\n			[if enb_txt_0]\r\n				<div class=\"ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0\">\r\n				[txt_0]\r\n				</div>\r\n			[endif]\r\n		</div>\r\n		<div class=\"ppsRightCol\">\r\n			[if enb_txt_1]\r\n				<div class=\"ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_1 ppsPopupTxt_1\">\r\n				[txt_1]\r\n				</div>\r\n			[endif]\r\n			<div style=\"clear: both;\"></div>\r\n			[if enb_subscribe]\r\n				<div class=\"ppsSubscribeShell\">\r\n					[sub_form_start]\r\n					[sub_fields_html]\r\n					<input type=\"submit\" name=\"submit\" value=\"[sub_btn_label]\" />\r\n					[sub_form_end]\r\n					<div style=\"clear: both;\"></div>\r\n				</div>\r\n			[endif]\r\n			[if enb_sm]\r\n				<div class=\"ppsSm\">\r\n				[sm_html]\r\n				</div>\r\n			[endif]\r\n			[if enb_foot_note]\r\n				<div class=\"ppsFootNote\">\r\n				[foot_note]\r\n				</div>\r\n			[endif]\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	padding: 15px;\r\n  	font-family: Georgia, Times, serif;\r\n	font-size: 13px;\r\n	line-height: 21px;\r\n	font-weight: normal;\r\n	color: #000;\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: border-box;\r\n	-moz-box-sizing:    border-box;\r\n	box-sizing:         border-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n	display: block;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupInner {\r\n  {% if popup.params.tpl.enb_subscribe or popup.params.tpl.enb_foot_note or popup.params.tpl.enb_sm %}\r\n  	width: 60%;\r\n  	box-shadow: rgba(32,32,32,1) 0 4px 20px;\r\n  	border-radius:3px;\r\n	[else]\r\n  	width: 100%;\r\n  	[endif]\r\n  	display: block;\r\n  	float: left;\r\n  	margin-top: 30px;\r\n	[if bg_type_0 == \'color\']\r\n	background: -moz-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* ff3.6+ */\r\n	background: -webkit-gradient(radial, center center, 0px, center center, 100%, color-stop(0%, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }}), color-stop(100%, [bg_color_0])); /* safari4+,chrome */\r\n	background:-webkit-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* safari5.1+,chrome10+ */\r\n	background: -o-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* opera 11.10+ */\r\n	background: -ms-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* ie10+ */\r\n	background:radial-gradient(ellipse at center, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* w3c */\r\n	filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'{{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }}\', endColorstr=\'[bg_color_0]\',GradientType=1 ); /* ie6-9 */\r\n  	[elseif bg_type_0 == \'img\']\r\n  	background-image: url(\"[bg_img_0]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n  	\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	color: #56912d;\r\n	font-family: \'arial\', arial;\r\n	font-size: 30px;\r\n	letter-spacing: -1px;\r\n	line-height: 40px;\r\n	letter-spacing: -1px;\r\n	font-weight: bold;\r\n	margin-top: 15px;\r\n	padding-left: 20px;\r\n	text-shadow: 0px 0px 1px #56912d;\r\n	-moz-text-shadow: 0px 0px 1px #56912d;\r\n	-webkit-text-shadow: 0px 0px 1px #56912d;\r\n  	\r\n}\r\n#ppsPopupShell_[ID] .ppsRightCol {\r\n	display: table-cell;\r\n  	border-radius:3px;\r\n  	width: 40%;\r\n  	height: 110%;\r\n	display: block;\r\n  	float: right;\r\n  	box-shadow: rgba(32,32,32,1) 0 4px 20px;\r\n  	padding: 10px 0;\r\n  	[if bg_type_1 == \'color\']\r\n  	background: -moz-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_1, 50) }} 0%, [bg_color_1] 100%); /* ff3.6+ */\r\n	background: -webkit-gradient(radial, center center, 0px, center center, 100%, color-stop(0%, {{ adjust_brightness(popup.params.tpl.bg_color_1, 50) }}), color-stop(100%, [bg_color_1])); /* safari4+,chrome */\r\n	background:-webkit-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_1, 50) }} 0%, [bg_color_1] 100%); /* safari5.1+,chrome10+ */\r\n	background: -o-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_1, 50) }} 0%, [bg_color_1] 100%); /* opera 11.10+ */\r\n	background: -ms-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_1, 50) }} 0%, [bg_color_1] 100%); /* ie10+ */\r\n  background:radial-gradient(ellipse at center, {{ adjust_brightness(popup.params.tpl.bg_color_1, 50) }} 0%, [bg_color_1] 100%); /* w3c */\r\n	filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'{{ adjust_brightness(popup.params.tpl.bg_color_1, 50) }}\', endColorstr=\'[bg_color_1]\',GradientType=1 ); /* ie6-9 */\r\n  	[elseif bg_type_1 == \'img\']\r\n  	background-image: url(\"[bg_img_1]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n  \r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell form {\r\n	padding: 30px 30px 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	width: 100%;\r\n  	margin-bottom: 10px;\r\n  	height: 40px;\r\n  	border: 1px solid #d1b36d;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=text],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSu