(13, 'Ready', 1, 0, '', '<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<div id=\"close\"><a href=\"#\" class=\"ppsPopupClose ppsPopupClose_[close_btn]\"></a></div>\r\n	<div class=\"ppsInnerTblContent\">\r\n		<div class=\"ppsPopupListsInner ppsPopupInner\">\r\n			<div style=\"clear: both;\"></div>\r\n			<div class=\"ppsRightCol\">\r\n				[if enb_label]\r\n					<div class=\"label-window\">\r\n						<div class=\"ppsPopupLabel ppsPopupListsLabel\"><h2>[label]</h2></div>\r\n					</div>\r\n				[endif]\r\n				[if enb_txt_0]\r\n					<div class=\"ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0\">\r\n					[txt_0]\r\n					</div>\r\n				[endif]\r\n				<div style=\"clear: both;\"></div>\r\n				[if enb_subscribe]\r\n					<div class=\"ppsSubscribeShell\">\r\n						[sub_form_start]\r\n						[sub_fields_html]\r\n						<input type=\"submit\" name=\"submit\" value=\"[sub_btn_label]\" />\r\n						[sub_form_end]\r\n						<div style=\"clear: both;\"></div>\r\n					</div>\r\n				[endif]\r\n				[if enb_sm]\r\n					<div class=\"ppsSm\">\r\n					[sm_html]\r\n					</div>\r\n				[endif]\r\n				[if enb_foot_note]\r\n					<div class=\"ppsFootNote\">\r\n					[foot_note]\r\n					</div>\r\n				[endif]\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	padding: 15px;\r\n  	font-family: Georgia, Times, serif;\r\n	font-size: 13px;\r\n	line-height: 21px;\r\n	font-weight: normal;\r\n	color: #000;\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: content-box;\r\n	-moz-box-sizing:    content-box;\r\n	box-sizing:         content-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n	display: table;\r\n  	[if bg_type_0 == \'color\']\r\n	background: -moz-radial-gradient(center, ellipse cover, {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* ff3.6+ */\r\n	background: -webkit-gradient(radial, center center, 0px, center center, 100%, colo