(28, 'Smart', 1, 0, '', '<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<a href=\"#\" class=\"ppsPopupClose\"></a>\r\n	<div class=\"ppsPopupListsInner\">\r\n		<div class=\"ppsPopupTblCols\">\r\n			<div class=\"ppsPopupLeftCol\">\r\n				[if bg_type_2 == \'img\']\r\n				<img src=\"[bg_img_2]\" />\r\n				[endif]\r\n			</div>\r\n			<div class=\"ppsPopupRightCol\">\r\n				<div class=\"ppsBigArrow\"></div>\r\n				[if enb_label]\r\n					<div class=\"ppsPopupLabel\">[label]</div>\r\n				[endif]\r\n				[if enb_txt_0]\r\n					<div class=\"ppsPopupTxt ppsPopupTxt_0\">[txt_0]</div>\r\n				[endif]\r\n				[if enb_subscribe]\r\n					<div class=\"ppsSubscribeShell\">\r\n						[sub_form_start]\r\n						[sub_fields_html]\r\n						<input type=\"submit\" name=\"submit\" value=\"[sub_btn_label]\" />\r\n						[sub_form_end]\r\n					</div>\r\n				[endif]\r\n				[if enb_sm]\r\n					<div class=\"ppsSm\">\r\n					[sm_html]\r\n					</div>\r\n				[endif]\r\n				[if enb_foot_note]\r\n					<div class=\"ppsFootNote\">\r\n					[foot_note]\r\n					</div>\r\n				[endif]\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	font-family: Helvetica,Arial,sans-serif;\r\n  	font-size: 14px;\r\n  	[if bg_type_0 == \'img\']\r\n  	background-image: url(\"[bg_img_0]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: content-box;\r\n	-moz-box-sizing:    content-box;\r\n	box-sizing:         content-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	color: [bg_color_1];\r\n    font-size: 25px;\r\n    font-weight: bold;\r\n	line-height: 1.2;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupListsInner {\r\n  	border: 3px solid #bac0ac;\r\n  	-webkit-box-shadow: inset 0 0 0 5px #fff, 0 10px 25px rgba(0,0,0,0.5);\r\n	-moz-box-shadow: inset 0 0 0 5px #fff, 0 10px 25px rgba(0,0,0,0.5);\r\n	box-shadow: inset 0 0 0 5px #fff, 0 10px