(32, 'Simple iFrame', 1, 0, '', '<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<a href=\"#\" class=\"ppsPopupClose ppsPopupClose_[close_btn]\"></a>\r\n	<iframe class=\"ppsMainFrame\" src=\"[iframe_url]\"></iframe>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	height: [height][height_measure];\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: content-box;\r\n	-moz-box-sizing:    content-box;\r\n	box-sizing:         content-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsMainFrame {\r\n  	width: 100%;\r\n  	height: 100%;\r\n  	border: 8px solid [bg_color_0];\r\n  	border-radius: 5px;\r\n  	padding: 0;\r\n  	margin: 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n  	top: 15px;\r\n  	right: 10px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}', 'simple-iframe.jpg', 1, 1, 1, 4, 0, 0, 0, '2015-01-10 13:29:43', 30, 0),
(33, 'Simple HTML', 1, 0, '', '<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<a href=\"#\" class=\"ppsPopupClose ppsPopupClose_[close_btn]\"></a>\r\n	<div class=\"ppsInnerTblContent\">\r\n		[txt_0]\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	padding: 15px;\r\n  	font-family: \'Helvetica\', arial;\r\n	font-size: 14px;\r\n	line-height: 21px;\r\n	font-weight: normal;\r\n	color: #000;\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: content-box;\r\n	-moz-box-sizing:    content-box;\r\n	box-sizing:         content-box;\r\n}\r\n#ppsPopupShell_[ID] p {\r\n	margin: 14px 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n	height: 100%;\r\n  	[if bg_type_1 == \'color\']\r\n  	border: 8px solid [bg_color_1];\r\n  	[endif]\r\n  	border-radius: 5px;\r\n  	padding: 10px;\r\n  	[if bg_type_0 == \'color\']\r\n  	background-color: [bg_color_0];\r\n  	[elseif bg_type_0 == \'img\']\r\n  	background-image: url(\"[bg_img_0]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}', 'simple-html.jpg', 1, 1, 1, 5, 0, 0, 0, '2015-01-10 13:29:43', 31, 0),
(34, 'HTML 2 Columns', 1, 0, '', '<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<a href=\"#\" class=\"ppsPopupClose ppsPopupClose_[close_btn]\"></a>\r\n	<div class=\"ppsInnerTblContent\">\r\n      	[if enb_txt_0]\r\n      	<div class=\"ppsCol\">[txt_0]</div>\r\n      	[endif]\r\n      	[if enb_txt_1]\r\n      	<div class=\"ppsCol\">[txt_1]</div>\r\n      	[endif]\r\n      	<div style=\"clear: both;\"></div	>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	padding: 15px;\r\n  	font-family: \'Helvetica\', arial;\r\n	font-size: 14px;\r\n	line-height: 21px;\r\n	font-weight: normal;\r\n	color: #fff;\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: border-box;\r\n	-moz-box-sizing:    border-box;\r\n	box-sizing:         border-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n	height: 100%;\r\n  	[if bg_type_1 == \'color\']\r\n  	border: 8px solid [bg_color_1];\r\n  	[endif]\r\n  	border-radius: 5px;\r\n  	padding: 10px;\r\n  	[if bg_type_0 == \'color\']\r\n  	background-color: [bg_color_0];\r\n  	[elseif bg_type_0 == \'img\']\r\n  	background-image: url(\"[bg_img_0]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsCol {\r\n	float: left;\r\n  	margin: 0;\r\n  	padding: 5px;\r\n}\r\n#ppsPopupShell_[ID] .ppsCol img {\r\n	width: 100% !important;\r\n  	height: auto !important;\r\n}\r\n{% if [enb_txt_0] and [enb_txt_1] %}\r\n#ppsPopupShell_[ID] .ppsCol {\r\n	width: 50%;\r\n}\r\n{% endif %}\r\n\r\n', 'html-2-columns.jpg', 1, 1, 1, 5, 0, 0, 0, '2015-01-10 13:29:43', 32, 0),
(35, 'PDF PopUp', 1, 0, '', '<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<a href=\"#\" class=\"ppsPopupClose ppsPopupClose_[close_btn]\"></a>\r\n	<iframe class=\"ppsMainFrame\" src=\"https://docs.google.com/gview?url=[pdf_url]&embedded=true\"></iframe>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	height: [height][height_measure];\r\n  	[if bg_type_0 == \'color\']\r\n	background-color: [bg_color_0];\r\n  	[elseif bg_type_0 == \'img\']\r\n  	background-image: url(\"[bg_img_0]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: content-box;\r\n	-moz-box-sizing:    content-box;\r\n	box-sizing:         content-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsMainFrame {\r\n  	width: 100%;\r\n  	height: 100%;\r\n  	[if enb_bg_0]\r\n  	border: 8px solid [bg_color_0];\r\n  	[endif]\r\n  	border-radius: 5px;\r\n  	padding: 0;\r\n  	margin: 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n  	top: 15px;\r\n  	right: 10px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}', 'pdf-popup.jpg', 1, 1, 1, 6, 0, 0, 0, '2015-01-10 13:29:43', 33, 0),
(38, 'Clear PopUp', 1, 0, '', '<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<a href=\"#\" class=\"ppsPopupClose ppsPopupClose_[close_btn]\"></a>\r\n	<div class=\"ppsInnerTblContent\">\r\n		[if enb_label]\r\n			<div class=\"ppsPopupLabel\">[label]</div>\r\n		[endif]\r\n		[if enb_txt_0]\r\n			<div class=\"ppsPopupTxt ppsPopupTxt_0\">[txt_0]</div>\r\n		[endif]\r\n		[if enb_btn_0]\r\n      		<a class=\"ppsBtn ppsBtn_0[if is_close_btn_0] ppsPopupClose[endif]\" href=\"[btn_url_0]\">[btn_txt_0]</a>\r\n      	[endif]\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	padding: 15px;\r\n  	font-family: \"Open Sans\",arial;\r\n	font-size: 16px;\r\n	line-height: 1.475;\r\n	font-weight: normal;\r\n	color: #fff;\r\n  	text-shadow: 1px 1px 1px #000000;\r\n  	text-align: center;\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: content-box;\r\n	-moz-box-sizing:    content-box;\r\n	box-sizing:         content-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n	background-color: transparent;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	font-size: 32px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsBtn {\r\n  	display: inline;\r\n  	margin: 0;\r\n  	padding: 5px 20px;\r\n  	border-radius: 5px;\r\n  	transition-duration: 0.3s;\r\n  	text-decoration: none !important;\r\n  	color: #fff;\r\n  	font-size: 24px;\r\n  	border: 1px solid #000;\r\n  	color: #000;\r\n  	[if bg_type_0 == \'color\']\r\n	background:  [bg_color_0]; /* Old browsers */\r\nbackground: -moz-linear-gradient(top,   {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%, [bg_color_0] 100%); /* FF3.6-15 */\r\nbackground: -webkit-linear-gradient(top,   {{ adjust_brightness(popup.params.tpl.bg_color_0, 50) }} 0%,[bg_color_0] 100%); /* Chrome10-25,Safari5.1-6 *