(42, 'Sign Up Classic', 1, 0, '', '<link href=\"https://fonts.googleapis.com/css?family=Dancing+Script|Gloria+Hallelujah|Hind|Pacifico|Satisfy\" rel=\"stylesheet\"> \r\n<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<a href=\"#\" class=\"ppsPopupClose ppsPopupClose_[close_btn]\"></a>\r\n	<div class=\"ppsInnerTblContent\">\r\n		<div class=\"ppsPopupListsInner ppsPopupInner\">\r\n			[if enb_label]\r\n				<div class=\"ppsPopupLabel ppsPopupListsLabel\">[label]</div>\r\n			[endif]\r\n			<div style=\"clear: both;\"></div>\r\n			[if enb_txt_0]\r\n				<div class=\"ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0\">\r\n				[txt_0]\r\n				</div>\r\n			[endif]\r\n			[if enb_subscribe]\r\n				<div class=\"ppsSubscribeShell\">\r\n					[sub_form_start]\r\n					[sub_fields_html]\r\n					<input type=\"submit\" name=\"submit\" value=\"[sub_btn_label]\" />\r\n					[sub_form_end]\r\n					<div style=\"clear: both;\"></div>\r\n				</div>\r\n			[endif]\r\n			<div style=\"clear: both;\"></div>\r\n			<div class=\"ppsRightCol\">\r\n				[if enb_sm]\r\n					<div style=\"clear: both;\"></div>\r\n					<div class=\"ppsSm\">\r\n					[sm_html]\r\n					</div>\r\n				[endif]\r\n				[if enb_foot_note]\r\n					<div class=\"ppsFootNote\">\r\n					[foot_note]\r\n					</div>\r\n				[endif]\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	padding: 15px;\r\n  	font-family: \"Hind\",\"arial\",arial;\r\n	font-size: 13px;\r\n	line-height: 21px;\r\n	font-weight: normal;\r\n	color: #4d4d4d;\r\n  	text-align: center;\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: border-box;\r\n	-moz-box-sizing:    border-box;\r\n	box-sizing:         border-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n	display: table;\r\n  	width: 100%;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupInner {\r\n  	width: 100%;\r\n  	display: table-cell;\r\n  	padding: 40px;\r\n	[if bg_type_0 == \'color\']\r\n	background-color: [bg_color_0];\r\n  	background-image: none;\r\n  	[elseif bg_type_0 == \'img\']\r\n  	background-image: url(\"[bg_img_0]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	font-family: \"Dancing Script\", arial;\r\n	font-size: 40px;\r\n	line-height: 40px;\r\n	font-weight: bold;\r\n  	margin-bottom: 30px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell form {\r\n	margin-bottom: 20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	width: 100%;\r\n  	margin-bottom: 10px;\r\n  	height: 40px;\r\n  	border: none;\r\n	border-radius: 0;\r\n  	font-size: 17px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=text],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n  	padding-left: 10px;\r\n  	\r\n  	background-color: #fff;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelect {\r\n	display: table;\r\n  	text-align: left;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelectLabel,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	display: table-cell;\r\n  	color: #000;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell .ppsSubSelectLabel {\r\n	opacity: 0.5;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	width: 100%;\r\n  	background-color: transparent;\r\n  	height: 40px;\r\n  	border: none;\r\n  	margin-left: -4px;\r\n  	font-size: 17px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	font-family: inherit;\r\n  	height: auto;\r\n    padding-top: 5px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit] {\r\n	border-color: #000;\r\n  	[if bg_type_1 == \'color\']\r\n  	background: [bg_color_1] 100%;\r\n  	background-image: none;\r\n  	border: 1px solid #fff;\r\n  	box-shadow: 0 0 0 4px [bg_color_1];\r\n  	width: calc(100% - 8px);\r\n  	[elseif bg_type_1 == \'img\']\r\n  	background-image: url(\"[bg_img_1]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n  	color: #fff;\r\n  	cursor: pointer;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit]:hover {\r\n   border-width: 2px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 {\r\n  	width: 100%;\r\n	font-size: 14px;\r\n  	margin-bottom: 20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n	top: 15px;\r\n  	right: 10px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose.ppsPopupClose_lists_black {\r\n 	top: 0 !important;\r\n  	right: 0 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote {\r\n	color: #585858;\r\n    font-family: \"Helvetica Neue\",Helvetica,Arial,sans-serif;\r\n    font-size: x-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n  	margin: 5px 30px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSm {\r\n	margin-top:20px;\r\n}', 'sign-up-classic.jpg', 1, 1, 1, 1, 0, 0, 0, '2015-01-10 13:29:43', 1, 0);
INSERT INTO `wp_pps_popup` (`id`, `label`, `active`, `original_id`, `params`, `html`, `css`, `img_preview`, `show_on`, `show_to`, `show_pages`, `type_id`, `views`, `unique_views`, `actions`, `date_created`, `sort_order`, `show_in_admin_area`) VALUES
(43, 'Smart New Edition', 1, 0, '', '<link href=\"https://fonts.googleapis.com/css?family=Montserrat\" rel=\"stylesheet\">\r\n<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<a href=\"#\" class=\"ppsPopupClose\"></a>\r\n	<div class=\"ppsPopupListsInner\">\r\n		<div class=\"ppsPopupTblCols\">\r\n			<div class=\"ppsPopupLeftCol\">\r\n				[if bg_type_2 == \"img\"]\r\n				<img src=\"[bg_img_2]\" />\r\n				[endif]\r\n			</div>\r\n			<div class=\"ppsPopupRightCol\">\r\n				<div class=\"ppsBigArrow\"></div>\r\n				[if enb_label]\r\n					<div class=\"ppsPopupLabel\">[label]</div>\r\n				[endif]\r\n				[if enb_txt_0]\r\n					<div class=\"ppsPopupTxt ppsPopupTxt_0\">[txt_0]</div>\r\n				[endif]\r\n				[if enb_subscribe]\r\n					<div class=\"ppsSubscribeShell\">\r\n						[sub_form_start]\r\n						<div class=\"ppsFormWrap\">\r\n						[sub_fields_html]\r\n						</div><!--\r\n						--><input type=\"submit\" name=\"submit\" value=\"[sub_btn_label]\" />\r\n						[sub_form_end]\r\n					</div>\r\n				[endif]\r\n				[if enb_sm]\r\n					<div class=\"ppsSm\">\r\n					[sm_html]\r\n					</div>\r\n				[endif]\r\n				[if enb_foot_note]\r\n					<div class=\"ppsFootNote\">\r\n					[foot_note]\r\n					</div>\r\n				[endif]\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	font-family: Helvetica,Arial,sans-serif;\r\n  	font-size: 14px;\r\n  	[if bg_type_0 == \"img\"]\r\n  	background-image: url(\"[bg_img_0]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: border-box;\r\n	-moz-box-sizing:    border-box;\r\n	box-sizing:         border-box;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsPopupListsInner {\r\n  	[if bg_type_0 == \"color\"]\r\n	background: {{ adjust_brightness(popup.params.tpl.bg_color_0, 255) }}; /* Old browsers */\r\n	background: -moz-linear-gradient(top,  {{ adjust_brightness(popup.params.tpl.bg_color_0, 255) }} 0%, {{ adjust_brightness(popup.params.tpl.bg_color_0, 125) }} 50%, {{ adjust_brightness(popup.params.tpl.bg_color_0, 60) }} 75%, {{ adjust_brightness(popup.params.tpl.bg_color_0, 0) }} 100%); /* FF3.6-15 */\r\n	background: -webkit-linear-gradient(top,  {{ adjust_brightness(popup.params.tpl.bg_color_0, 255) }} 0%,{{ adjust_brightness(popup.params.tpl.bg_color_0, 125) }} 50%,{{ adjust_brightness(popup.params.tpl.bg_color_0, 60) }} 75%,{{ adjust_brightness(popup.params.tpl.bg_color_0, 0) }} 100%); /* Chrome10-25,Safari5.1-6 */\r\n	background: linear-gradient(to bottom,  {{ adjust_brightness(popup.params.tpl.bg_color_0, 255) }} 0%,{{ adjust_brightness(popup.params.tpl.bg_color_0, 125) }} 50%,{{ adjust_brightness(popup.params.tpl.bg_color_0, 60) }} 75%,{{ adjust_brightness(popup.params.tpl.bg_color_0, 0) }} 100%); /* W3C, IE10+, FF16+, Chrome26+, Opera12+, Safari7+ */\r\n	filter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\"{{ adjust_brightness(popup.params.tpl.bg_color_0, 255) }}\", endColorstr=\"{{ adjust_brightness(popup.params.tpl.bg_color_0, 0) }}\",GradientType=0 ); /* IE6-9 */\r\n	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTblCols {\r\n	display: table;\r\n  	padding: 10px 10px 10px 30px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLeftCol {\r\n	display: table-cell;\r\n  	[if enb_subscribe]\r\n  	width: 30%;\r\n  	[else]\r\n  	width: 30%;\r\n  	min-height: 60%;\r\n  	[endif]\r\n  	vertical-align: middle;\r\n    text-align: center;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupRightCol {\r\n  	width: 70%;\r\n	display: table-cell;\r\n  	border-radius: 8px;\r\n	-moz-border-radius: 8px;\r\n	-webkit-border-radius: 8px;\r\n  	margin: 8px 5px 5px 5px;\r\n  	text-align: left;\r\n  	padding: 30px 0 30px 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input::-webkit-input-placeholder { /* Chrome/Opera/Safari */\r\n    color: #838383;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input::-moz-placeholder { /* Firefox 19+ */\r\n    color: #838383;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input:-ms-input-placeholder { /* IE 10+ */\r\n    color: #838383;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input:-moz-placeholder { /* Firefox 18- */\r\n    color: #838383;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea::-webkit-input-placeholder { /* Chrome/Opera/Safari */\r\n    color: #838383;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea::-moz-placeholder { /* Firefox 19+ */\r\n    color: #838383;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea:-ms-input-placeholder { /* IE 10+ */\r\n    color: #838383;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea:-moz-placeholder { /* Firefox 18- */\r\n    color: #838383;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell {\r\n	display: block;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell form {\r\n	padding: 30px 0 0;\r\n  	text-align: left;\r\n    position: relative;\r\n}\r\n#ppsPopupShell_[ID] .ppsFormWrap {\r\n	display:inline-block;\r\n	width: 60%;\r\n	vertical-align: bottom;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=\"text\"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=\"email\"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=\"password\"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=\"email\"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	border: 1px solid transparent;\r\n	width: 100%;\r\n	-webkit-border-radius: 0px;\r\n	-moz-border-radius: 0px;\r\n	border-radius: 0px;\r\n	display:block;\r\n    font-size: 17px;\r\n	font-weight: normal;\r\n    color: #636363;\r\n	padding: 0 0 0 10px;\r\n	height: 40px;\r\n	margin: 10px 0 0 0;\r\n	\r\n  	[if bg_type_1 == \"img\"]\r\n  	background: url(\"[bg_img_1]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[else]\r\n  	background: [bg_color_1];\r\n  	[endif]\r\n  	\r\n  	[if bg_type_5 == \"color\"]\r\n  	color: [bg_color_5];\r\n  	[endif]\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	height: auto;\r\n	padding-top: 9px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeForm input:first-child {\r\n	margin-top: 0px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select  {\r\n	margin: 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  {\r\n	display: block;\r\n	font-size: 17px;\r\n	color: #636363;\r\n	margin-top: 10px;\r\n	text-align: left;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  span {\r\n	display: block;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit] {\r\n  	[if bg_type_3 == \"color\"]\r\n  	background: [bg_color_3];\r\n	background-image: none;\r\n  	[elseif bg_type_3 == \"img\"]\r\n  	background-image: url(\"[bg_img_3]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n	\r\n  	[if bg_type_4 == \"color\"]\r\n  	color: [bg_color_4];\r\n  	[endif]\r\n	\r\n    font-size: 17px;\r\n	font-weight: normal;\r\n  	cursor: pointer;\r\n  	width:  auto;\r\n    text-transform: uppercase;\r\n  	padding: 0px 20px;\r\n	height: 40px;\r\n	display:inline-block;\r\n	border: 1px solid transparent;\r\n	-webkit-border-radius: 0px;\r\n	-moz-border-radius: 0px;\r\n	border-radius: 0px;\r\n	vertical-align: bottom;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit]:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n  	right: -5px;\r\n	top: 2px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 .ppsTxtContent {\r\n	padding: 10px 10px 10px 50px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 p {\r\n	margin: 0;\r\n	padding: 0;\r\n	font-family: Montserrat;\r\n	font-size: 16px;\r\n    line-height: 24px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 {\r\n  	width: 90%;\r\n  	color: #4d4c4c;\r\n  	display: block;\r\n  	margin: 27px 0 0;\r\n    padding: 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupRightCol .ppsHeaderTxt2 {\r\n  	[if bg_type_6 == \"color\"]\r\n  	color: [bg_color_6] !important;\r\n  	[endif]\r\n	margin: 0;\r\n    padding: 0;\r\n	font-weight: bold;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	color: #4d4c4c;\r\n	line-height: 1.2;\r\n	margin: 0 10px 0 0;\r\n	color: #4d4c4c;\r\n	font-family: Montserrat;\r\n	font-size: 25px;\r\n    font-weight: normal;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote {\r\n  	[if enb_subscribe]\r\n    color: #000000;\r\n    font-family: \"Helvetica Neue\",Helvetica,Arial,sans-serif;\r\n    font-size: xx-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n    text-align: left;\r\n  	margin-left: 10px;\r\n  	[else]\r\n  	margin-top: 10px;\r\n  	color: #979696;\r\n    font-family: \"Helvetica Neue\",Helvetica,Arial,sans-serif;\r\n    font-size: xx-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n    text-align: left;\r\n    margin-left: 10px;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsSm{\r\n	[if enb_subscribe]\r\n  	[else]\r\n  	margin-top: 130px;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] li{\r\n	font-weight: bold;\r\n  	font-size: 13px;\r\n  	padding-top: 3px;\r\n	padding-bottom: 3px;\r\n  	color: #737E86;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubMsg{\r\n	clear: both;\r\n  	text-align: center;\r\n	width: 100%;\r\n}\r\n', 'smart2_p4.png', 1, 1, 1, 1, 0, 0, 0, '2015-01-13 13:52:48', 1, 0),
(44, 'Christmas Mistletoe', 1, 0, '', '<link href=\"https://fonts.googleapis.com/css?family=Great+Vibes|Lato\" rel=\"stylesheet\">\r\n<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<a href=\"#\" class=\"ppsPopupClose ppsPopupClose_[close_btn]\"></a>\r\n	<div class=\"ppsInnerTblContent\">\r\n		<div class=\"ppsPopupListsInner ppsPopupInner\">\r\n			[if bg_type_1 == \"img\"]\r\n			<div class=\"ppsWrapImgCrn ppsWrapImgLftCrn\">\r\n				<img class=\"ppsImgLftCrn\" src=\"[bg_img_1]\" alt=\"left image\"/>\r\n			</div>\r\n			[endif]\r\n			[if bg_type_2 == \"img\"]\r\n			<div class=\"ppsWrapImgCrn ppsWrapImgRghtCrn\">\r\n				<img class=\"ppsImgRghtCrn\" src=\"[bg_img_2]\" alt=\"rigth image\"/>\r\n			</div>\r\n			[endif]\r\n			[if enb_label]\r\n				<div class=\"ppsPopupLabel ppsPopupListsLabel\">[label]</div>\r\n			[endif]\r\n			<div style=\"clear: both;\"></div>\r\n			[if enb_txt_0]\r\n				<div class=\"ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0\">\r\n				[txt_0]\r\n				</div>\r\n			[endif]\r\n			[if enb_txt_1]\r\n				<div class=\"ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_1 ppsPopupTxt_1\">\r\n				[txt_1]\r\n				</div>\r\n			[endif]\r\n			[if enb_subscribe]\r\n				<div class=\"ppsSubscribeShell\">\r\n					[sub_form_start]\r\n					<div class=\"ppsFormWrap\">\r\n					[sub_fields_html]\r\n					</div><input class=\"butt\" type=\"submit\" name=\"submit\" value=\"[sub_btn_label]\" />\r\n					[sub_form_end]\r\n					<div style=\"clear: both;\"></div>\r\n				</div>\r\n			[endif]\r\n			<div style=\"clear: both;\"></div>\r\n			<div class=\"ppsBottomtCol\">\r\n				[if enb_sm]\r\n					<div style=\"clear: both;\"></div>\r\n					<div class=\"ppsSm\">\r\n					[sm_html]\r\n					</div>\r\n				[endif]\r\n				[if enb_foot_note]\r\n					<div class=\"ppsFootNote\">\r\n					[foot_note]\r\n					</div>\r\n				[endif]\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	font-family: \"Great Vibes\";\r\n	font-weight: normal;\r\n	[if bg_type_0 == \"color\"]\r\n	background-color: [bg_color_0];\r\n  	[elseif bg_type_0 == \"img\"]\r\n  	background-image: url(\"[bg_img_0]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: border-box;\r\n	-moz-box-sizing:    border-box;\r\n	box-sizing:         border-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupInner {\r\n	text-align: center;\r\n	color: #fff;\r\n  	width: 100%;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell {\r\n	width: 90%;\r\n	text-align: center;\r\n	display: inline-block;\r\n    margin: 40px 0 30px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell form {\r\n	display: inline-block;\r\n    position: relative;\r\n    text-align: left;\r\n    width: 60%;\r\n    z-index: 100;\r\n}\r\n\r\n/*For all Elements*/\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=\"email\"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=\"text\"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select,\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	font-family: \"Lato\";\r\n	font-size: 15px;\r\n	font-weight: normal;\r\n	border: 3px solid #fff;\r\n  	padding: 0 0 0 20px;\r\n	margin: 10px 0 0;\r\n	color: #fff;\r\n	width: 100%;\r\n	display: block;\r\n	vertical-align: top;\r\n	outline: none;\r\n	-webkit-border-radius: 0px;\r\n	-moz-border-radius: 0px;\r\n	border-radius: 0px;\r\n	\r\n  	[if bg_type_4 == \"color\"]\r\n  	background-color: [bg_color_4];\r\n    [elseif bg_type_4 == \"img\"]\r\n  	background-image: url(\"[bg_img_4]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n	[else]\r\n	background-color: transparent;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select  {\r\n	margin-top: 0;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeForm input:first-child {\r\n	margin-top: 0px;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  {\r\n	font-family: \"Lato\";\r\n	font-size: 15px;\r\n	font-weight: normal;\r\n	display: block;\r\n	width: 100%;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  span {\r\n	display: inline-block;\r\n	padding-right: 2px;\r\n	vertical-align: middle;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=radio],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=checkbox] {\r\n	vertical-align: middle;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=\"email\"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=\"text\"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select {\r\n	height: 42px;\r\n}\r\n#ppsPopupShell_[ID] .ppsFormWrap {\r\n	text-align: left;\r\n	width: 65%;\r\n	vertical-align: bottom;\r\n	display: inline-block;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit] {\r\n	font-family: \"Lato\";\r\n	font-size: 20px;\r\n	font-weight: normal;\r\n	width: 30%;\r\n  	text-align: center;\r\n 	cursor: pointer;\r\n  	text-decoration: none;\r\n  	color: #001933;\r\n  	display: inline-block;\r\n	vertical-align: bottom;\r\n	padding: 0px;\r\n	margin: 0;\r\n	border: none;\r\n	outline: none;\r\n	height: 42px;\r\n	-webkit-border-radius: 0px;\r\n	-moz-border-radius: 0px;\r\n	border-radius: 0px;\r\n	\r\n	[if bg_type_3 == \"color\"]\r\n  	background:[bg_color_3] !important;\r\n    [elseif bg_type_3 == \"img\"]\r\n  	background-image: url(\"[bg_img_3]\") !important;\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n}\r\n#ppsPopupShell_[ID] .ppsBottomtCol {\r\n	display: inline-block;\r\n	margin-bottom: 100px;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	display: inline-block;\r\n	font-size: 30px;\r\n	width: 90%;\r\n	position: relative;\r\n	margin: 50px 30px 0;\r\n	z-index: 100;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt {\r\n	width: 90%;\r\n	text-align: center;\r\n	display: inline-block;\r\n	position: relative;\r\n	z-index: 100;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt  p {\r\n	padding: 0px;\r\n	margin: 0px;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 {\r\n  	font-size: 50px;\r\n	line-height: 51px;\r\n	margin-top: 30px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 p {\r\n	line-height: 51px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_1 {\r\n	margin-top: 30px;\r\n  	font-size: 25px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubMsg {\r\n	display: block;\r\n	text-align: center;\r\n	width: 100%;\r\n	margin-top: 10px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n	top: 15px;\r\n  	right: -20px !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose.ppsPopupClose_lists_black {\r\n 	top: 0 !important;\r\n  	right: 0 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote{\r\n	color: #fff;\r\n    font-size: x-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n  	margin: 5px 30px;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsSm{\r\n	margin-top:20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupShell .ppsErrorMsg{\r\n  width: 200px;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsWrapImgCrn {\r\n	position: absolute;\r\n}\r\n#ppsPopupShell_[ID] .ppsWrapImgLftCrn {\r\n	top: 20px;\r\n	left: 12px;\r\n}\r\n#ppsPopupShell_[ID] .ppsWrapImgRghtCrn {\r\n	bottom: 20px;\r\n    right: 12px;\r\n}', 'christmas-mistletoe.png', 1, 1, 1, 11, 0, 0, 0, '2015-01-10 13:29:43', 44, 0);
