(46, 'Merry Christmas', 1, 0, '', '<link href=\"https://fonts.googleapis.com/css?family=Gentium+Basic\" rel=\"stylesheet\">\r\n<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<a href=\"#\" class=\"ppsPopupClose ppsPopupClose_[close_btn]\"></a>\r\n	<div class=\"ppsInnerTblContent\">\r\n		<div class=\"ppsPopupListsInner ppsPopupInner\">\r\n			<div class=\"ppsWrapTopImg\">\r\n				[if bg_type_1 == \"img\"]\r\n				<img src=\"[bg_img_1]\" class=\"ppsTopImg\"/>\r\n				[endif]\r\n			</div>\r\n			[if enb_label]\r\n				<div class=\"ppsPopupLabel ppsPopupListsLabel\">[label]</div>\r\n			[endif]\r\n			<div style=\"clear: both;\"></div>\r\n			[if enb_txt_0]\r\n				<div class=\"ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0\">\r\n				[txt_0]\r\n				</div>\r\n			[endif]\r\n			[if enb_subscribe]\r\n				<div class=\"ppsSubscribeShell\">\r\n					[sub_form_start]\r\n					[sub_fields_html]\r\n					<input type=\"submit\" name=\"submit\" value=\"[sub_btn_label]\" />\r\n					[sub_form_end]\r\n					<div style=\"clear: both;\"></div>\r\n				</div>\r\n			[endif]\r\n			<div style=\"clear: both;\"></div>\r\n			<div class=\"ppsBottomCol\">\r\n				[if enb_sm]\r\n					<div style=\"clear: both;\"></div>\r\n					<div class=\"ppsSm\">\r\n					[sm_html]\r\n					</div>\r\n				[endif]\r\n				[if enb_foot_note]\r\n					<div class=\"ppsFootNote\">\r\n					[foot_note]\r\n					</div>\r\n				[endif]\r\n			</div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	font-family: \"Gentium Basic\", arial;\r\n	font-size: 13px;\r\n	font-weight: normal;\r\n	color: #000;\r\n  	text-align: center;\r\n}\r\n\r\n#ppsPopupShell_[ID], #ppsPopupShell_[ID] * {\r\n	-webkit-box-sizing: border-box;\r\n	-moz-box-sizing:    border-box;\r\n	box-sizing:         border-box;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n  	width: 100%;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupInner {\r\n  	width: 100%;\r\n  	padding: 40px;\r\n	[if bg_t