nd-size: cover;\r\n  	[endif]\r\n	\r\n	-webkit-border-radius: 5px;\r\n	-moz-border-radius: 5px;\r\n	border-radius: 5px;\r\n	height: 41px;\r\n	text-transform: none;\r\n	margin: 10px 0 0;\r\n	-webkit-box-shadow: 2px 2px 6px 2px rgba(0, 0, 0, 0.75);\r\n	-moz-box-shadow: 2px 2px 6px 2px rgba(0, 0, 0, 0.75);\r\n	box-shadow: 2px 2px 6px 2px rgba(0, 0, 0, 0.75);\r\n	padding: 0;\r\n  	cursor: pointer;\r\n	color: #fff;\r\n	font-size: 20px;\r\n	font-family: \"Gentium Basic\", arial;\r\n	font-weight: normal;\r\n	border: 1px solid transparent;\r\n	width: 100%;\r\n	display: block;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=submit]:hover {\r\n	-webkit-box-shadow: 2px 2px  7px 2px rgba(0, 0, 0, 0.75);\r\n	-moz-box-shadow: 2px 2px  7px 2px rgba(0, 0, 0, 0.75);\r\n	box-shadow: 2px 2px  7px 2px rgba(0, 0, 0, 0.75);\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	font-size: 40px;\r\n	line-height: 40px;\r\n	font-weight: bold;\r\n  	margin: 0 30px 30px;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 {\r\n  	width: 100%;\r\n	font-size: 14px;\r\n  	margin: 0 30px 20px;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n	top: 15px;\r\n  	right: 10px;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose.ppsPopupClose_lists_black {\r\n 	top: 0 !important;\r\n  	right: 0 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote {\r\n	color: #585858;\r\n    font-size: x-small;\r\n    font-style: italic;\r\n    line-height: 14px;\r\n  	margin: 5px 30px;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsSm {\r\n	margin-top:20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubMsg {\r\n	margin: 0px;\r\n}', 'merry-christmas.png', 1, 1, 1, 11, 0, 0, 0, '2015-01-10 13:29:43', 46, 0);
