(47, 'Christmas Recipes', 1, 0, '', '<link href=\"https://fonts.google.com/?query=Open+sans&selection.family=Open+Sans:400,700\" rel=\"stylesheet\">\r\n<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<a href=\"#\" class=\"ppsPopupClose ppsPopupClose_[close_btn]\"></a>\r\n	<div class=\"ppsInnerTblContent\">\r\n		<div class=\"ppsPopupListsInner ppsPopupInner\">\r\n			<div class=\"ppsTopBgWrapper\">\r\n				<div class=\"ppsWrapImgWr\">\r\n					[if enb_label]\r\n						<div class=\"ppsPopupLabel ppsPopupListsLabel\">[label]</div>\r\n					[endif]\r\n					[if enb_txt_0]\r\n						<div class=\"ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0\">\r\n						[txt_0]\r\n						</div>\r\n					[endif]\r\n					[if enb_txt_1]\r\n						<div class=\"ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_1 ppsPopupTxt_1\">\r\n						[txt_1]\r\n						</div>\r\n					[endif]\r\n				</div>\r\n			</div>\r\n			<div style=\"clear: both;\"></div>\r\n			<div class=\"ppsBtmBgWrapper\">\r\n				[if enb_txt_2]\r\n					<div class=\"ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_2 ppsPopupTxt_2\">\r\n					[txt_2]\r\n					</div>\r\n				[endif]\r\n				[if enb_subscribe]\r\n					<div class=\"ppsSubscribeShell\">\r\n						[sub_form_start]\r\n						[sub_fields_html]\r\n						<input class=\"butt\" type=\"submit\" name=\"submit\" value=\"[sub_btn_label]\" />\r\n						[if enb_foot_note]\r\n							<a href=\"#\" class=\"ppsFootNote ppsPopupClose\">\r\n							[foot_note]\r\n							</a>\r\n						[endif]\r\n						[sub_form_end]\r\n						<div style=\"clear: both;\"></div>\r\n					</div>\r\n				[endif]\r\n				<div style=\"clear: both;\"></div>\r\n				[if enb_sm]\r\n					<div style=\"clear: both;\"></div>\r\n					<div class=\"ppsSm\">\r\n					[sm_html]\r\n					</div>\r\n					\r\n				[endif]\r\n			</div>\r\n			<div class=\"ppsBtmLine\"></div>\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	font-family: \"Open Sans\", arial;\r\n	font-size: 13px;\r\n	line-height: normal;\r\n	font-weight: normal;\r\n	color: #fff;\r\n}\r\n#ppsPopupShell_[ID] .ppsInnerTblContent {\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupInner {\r\n	[if bg_type_0 == \"color\"]\r\n	background-color: [bg_color_0];\r\n  	[elseif bg_type_0 == \"img\"]\r\n  	background-image: url(\"[bg_img_0]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n	\r\n	position: relative;\r\n	text-align: center;\r\n	padding: 0;\r\n}\r\n/*For all Elements*/\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=\"email\"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=\"text\"],\r\n#ppsPopupShell_[ID] .ppsSubscribeShell textarea {\r\n	margin: 10px 0 0;\r\n	font-size: 16px;\r\n	font-family: \"Open Sans\", arial;\r\n	-webkit-border-radius: 5px;\r\n	-moz-border-radius: 5px;\r\n	border-radius: 5px;\r\n	border: 2px solid #ccc;\r\n	width: 100%;\r\n	display:block;\r\n	background: #fff;\r\n	color: #4f4f4f;\r\n	text-align: center;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeForm input:first-child {\r\n	margin-top: 0px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell select  {\r\n	font-size: 16px;\r\n	font-family: \"Open Sans\", arial;\r\n	border: 2px solid #ccc;\r\n	display: inline-block;\r\n	background: #fff;\r\n	color: #4f4f4f;\r\n	text-align: center;\r\n	height: 45px;\r\n	-webkit-border-radius: 5px;\r\n	-moz-border-radius: 5px;\r\n	border-radius: 5px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  span {\r\n	display: inline-block;\r\n	padding-right: 2px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell label  {\r\n	color: #333333;\r\n    display: block;\r\n    margin: 10px 0 0;\r\n	font-size: 16px;\r\n	font-family: \"Open Sans\", arial;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input[type=text],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=password],#ppsPopupShell_[ID] .ppsSubscribeShell input[type=email] {\r\n    height: 45px;\r\n}\r\n#ppsPopupShell_[ID] input[type=submit] {\r\n	font-family: \"Open Sans\", arial;\r\n	display:inline-block;\r\n  	color: #fff;\r\n    font-size: 18px;\r\n	width: auto;\r\n	margin: 10px 0;\r\n	-webkit-border-radius: 35px;\r\n	-moz-border-radius: 35px;\r\n	border-radius: 35px;\r\n	border: 0 solid transparent;\r\n  	cursor: pointer;\r\n	text-transform: none;\r\n	padding: 13px 88px 7px 60px;\r\n	font-weight: 700;\r\n	text-shadow: 1px 2px 0px #86B80E;\r\n	text-decoration: none;text-decoration: none;\r\n	\r\n	-webkit-box-shadow: 1px 4px 0 0 rgba(134, 184, 14, 1);\r\n	-moz-box-shadow: 1px 4px 0 0 rgba(134, 184, 14, 1);\r\n	box-shadow: 1px 4px 0 0 rgba(134, 184, 14, 1);\r\n\r\n	background-color: #9cd610;\r\n	background-image: url(\"[PPS_ASSETS_URL]img/assets/365-1-arr-dwn.png\");\r\n    background-position: 79% 13px;\r\n    background-repeat: no-repeat;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell input.butt + a.ppsPopupClose {\r\n	display: inline-block !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubscribeShell {\r\n    display: inline-block;\r\n    margin: 20px 0 20px;\r\n    width: 60%;\r\n	position: relative;\r\n	z-index: 100;\r\n}\r\n#ppsPopupShell_[ID] .ppsTopBgWrapper {\r\n	[if bg_type_1 == \"color\"]\r\n	background: [bg_color_1];\r\n  	[elseif bg_type_1 == \"img\"]\r\n  	background-image: url(\"[bg_img_1]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n	\r\n	padding: 70px 0 0;\r\n	position: relative;\r\n}\r\n#ppsPopupShell_[ID] .ppsWrapImgWr {\r\n	[if bg_type_2 == \"color\"]\r\n	background: {{ hex_to_rgba_str(popup.params.tpl.bg_color_2, 0.5) }};\r\n  	[elseif bg_type_2 == \"img\"]\r\n  	background-image: url(\"[bg_img_2]\");\r\n  	background-repeat: no-repeat;\r\n  	background-size: cover;\r\n  	[endif]\r\n	\r\n	display: inline-block;\r\n    min-height: 130px;\r\n    padding: 10px 0;\r\n    text-align: center;\r\n    width: 100%;\r\n}\r\n#ppsPopupShell_[ID] .ppsImgWr {\r\n	display: inline-block;\r\n	max-width: 100%;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupLabel {\r\n	font-size: 50px;\r\n	position: relative;\r\n	z-index: 100;\r\n	width: 90%;\r\n	display: inline-block;\r\n	padding-top: 30px;\r\n	font-family: \"Open Sans\", arial;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt {\r\n	margin: 0;\r\n	padding: 0;\r\n	text-align: center;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt p {\r\n	display: inline-block;\r\n    margin: 0;\r\n    padding: 0;\r\n    width: 90%;\r\n	position: relative;\r\n	z-index: 100;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_0 {\r\n    font-size: 63px;\r\n    font-weight: bold;\r\n	font-family: \"Open Sans\", arial;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_1 {\r\n    color: #ffb2b2;\r\n    font-size: 56px;\r\n    font-weight: bold;\r\n    line-height: 51px;\r\n	font-family: \"Open Sans\", arial;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupTxt_2 {\r\n    color: #333333;\r\n    font-size: 21px;\r\n    font-weight: bold;\r\n	font-family: \"Open Sans\", arial;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsBtmBgWrapper {\r\n	padding: 20px 0 0;\r\n	position: relative;\r\n}\r\n#ppsPopupShell_[ID] .ppsBtnOne:hover {\r\n	text-decoration: none;\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsBtmLine {\r\n	height: 5px;\r\n	\r\n	[if bg_type_3 == \"color\"]\r\n	background: {{ hex_to_rgba_str(popup.params.tpl.bg_color_3, 0.5) }} !important;\r\n  	[elseif bg_type_3 == \"img\"]\r\n  	background-image: url(\"[bg_img_3]\") !important;\r\n  	background-repeat: no-repeat !important; \r\n  	background-size: cover !important;\r\n  	[endif]\r\n}\r\n\r\n#ppsPopupShell_[ID] .ppsPopupClose {\r\n	background-repeat: no-repeat;\r\n  	cursor: pointer;\r\n	z-index: 1000;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose.ppsPopupClose_lists_black {\r\n 	top: 0 !important;\r\n  	right: 0 !important;\r\n}\r\n#ppsPopupShell_[ID] .ppsPopupClose:hover {\r\n	opacity: 0.8;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote {\r\n	border-bottom: 2px dotted #b7b7b7;\r\n    color: #b7b7b7;\r\n	display: none !important;\r\n	margin: 10px 0;\r\n	text-decoration: none;	\r\n	background: none !important;\r\n	font-size: 16px;\r\n    height: auto !important;\r\n    position: static !important;\r\n    width: auto !important;\r\n	top: 0 !important;\r\n	word-wrap: break-word;\r\n}\r\n#ppsPopupShell_[ID] .ppsFootNote:hover {\r\n	text-decoration: none;\r\n}\r\n#ppsPopupShell_[ID] .ppsSm{\r\n	margin-top:20px;\r\n}\r\n#ppsPopupShell_[ID] .ppsSubMsg{\r\n	clear: both;\r\n  	text-align: center;\r\n}', 'christmas-1-prev.png', 1, 1, 1, 11, 0, 0, 0, '2015-01-10 13:29:43', 47, 0),
(48, 'Christmas mood', 1, 0, '', '<link href=\"https://fonts.googleapis.com/css?family=Alex+Brush|Josefin+Sans\" rel=\"stylesheet\">\r\n<div id=\"ppsPopupShell_[ID]\" class=\"ppsPopupShell ppsPopupListsShell\">\r\n	<a href=\"#\" class=\"ppsPopupClose ppsPopupClose_[close_btn]\"></a>\r\n	<div class=\"ppsInnerTblContent\">\r\n		<div class=\"ppsPopupListsInner ppsPopupInner\">\r\n			<div class=\"ppsWrapTopImg\">\r\n				[if bg_type_1 == \"img\"]\r\n				<img src=\"[bg_img_1]\" class=\"ppsTopImg\"/>\r\n				[endif]\r\n			</div>\r\n			[if enb_label]\r\n				<div class=\"ppsPopupLabel ppsPopupListsLabel\">[label]</div>\r\n			[endif]\r\n			[if enb_txt_0]\r\n				<div class=\"ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_0 ppsPopupTxt_0\">\r\n				[txt_0]\r\n				</div>\r\n				<div class=\"ppsTxt1Separator\"></div>\r\n			[endif]\r\n			[if enb_txt_1]\r\n				<div class=\"ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_1 ppsPopupTxt_1\">\r\n				[txt_1]\r\n				</div>\r\n			[endif]\r\n			<div style=\"clear: both;\"></div>\r\n			[if enb_subscribe]\r\n				<div class=\"ppsSubscribeShell\">\r\n					[sub_form_start]\r\n					[sub_fields_html]\r\n					<input class=\"butt\" type=\"submit\" name=\"submit\" value=\"[sub_btn_label]\" />\r\n					[sub_form_end]\r\n					<div style=\"clear: both;\"></div>\r\n				</div>\r\n			[endif]\r\n			[if enb_txt_2]\r\n				<div class=\"ppsPopupTxt ppsPopupClassyTxt ppsPopupClassyTxt_2 ppsPopupTxt_2\">\r\n				[txt_2]\r\n				</div>\r\n			[endif]\r\n			<div class=\"ppsTxt1Separator\"></div>\r\n			[if enb_foot_note]\r\n				<a href=\"#\" class=\"ppsFootNote ppsPopupClose\">\r\n				[foot_note]\r\n				</a>\r\n			[endif]\r\n			\r\n			<div style=\"clear: both;\"></div>\r\n			[if enb_sm]\r\n				<div style=\"clear: both;\"></div>\r\n				<div class=\"ppsSm\">\r\n				[sm_html]\r\n				</div>\r\n			[endif]\r\n			\r\n		</div>\r\n	</div>\r\n</div>', '#ppsPopupShell_[ID] {\r\n	width: [width][width_measure];\r\n  	font-family: arial;\r\n	font-size: 13px;\r\n	font-weight: normal;\